entries.content:
"name": "仓田武雄", "Kurata Takeo", "くらた たけお"
  "alias": [
    "仓田",
    "三等陆曹",
    "萌猫耳者",
    "特区侦察员"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "黑色的短发，修剪得比较整齐，典型的自卫官发型，带着一股属于年轻人的活力。",
    "eyes": "黑色的瞳孔，眼神中透着一种纯粹。在谈论ACG话题或看到猫耳亚人时，眼中会闪烁着异样的狂热光芒。",
    "outfit": "主要穿着陆上自卫队的迷彩战斗服。由于是高机动车的驾驶员，身上常挂着相关的战术装具。在特区行动时，即便穿着严肃的军装，眼神也总是在搜索着“人外娘”。",
    "physique": "身高约175cm左右，现年21岁。体格适中，虽然没有像富田那样拥有爆炸性的肌肉，但作为一线自卫官，其耐力和反应速度通过了严格的考核，尤其在驾驶方面展现了极高的天赋。",
    "BWH": "未知",
    "accessories": [
      "自卫队身份牌",
      "高机动车钥匙",
      "个人随身携带的动漫周边或同人志（受到伊丹的影响）"
    ]
  },
  "personality": {
    "traits": [
      "资深御宅族",
      "猫耳控（萌猫耳）",
      "纯情",
      "忠诚勇敢",
      "优秀的驾驶员",
      "行动派"
    ],
    "likes": [
      "猫耳亚人（特别是佩露西亚）",
      "萌系文化、动画、漫画",
      "与伊丹队长交流宅心得",
      "驾驶高机动车在特区驰骋"
    ],
    "dislikes": [
      "伤害女性（尤其是猫耳亚人）的行为",
      "错过关键的动漫讨论",
      "繁文缛节",
      "破坏宁静生活的战火"
    ]
  },
  "background": {
    "identity": "陆上自卫队三等陆曹，隶属于特地派遣方面队第三侦察队。原驻屯于北海道名寄。他是第三侦察队中驾驶技术最出色的成员之一。在伊丹耀司的带领下，他第一批跨越“门”进入特区。作为一名核心御宅族，他在特区找到了属于自己的“天堂”——真实的猫耳亚人。在故事的中后期，面对国家层面的撤退指令与保护所爱之人之间的冲突，他展现出了极大的个人勇气。",
    "achievements": [
      "作为第三侦察队成员，多次执行高危的特区深入侦察任务。",
      "在阿尔努斯防卫战以及后续的多场冲突中，以精准的驾驶技术确保了小队的机动性。",
      "在特区成功实践了自己的“萌猫耳”理想，并赢得了猫种亚人佩露西亚的芳心。",
      "在“韦驮天”撤退指令下达的混乱局势中，违抗或规避部分僵硬指令，毅然投入到营救和保护佩露西亚的个人战争中。"
    ]
  },
  "relationships": {
    "伊丹耀司": {
      "nature": "长官、宅友、精神导师",
      "description": "由于共同的宅男爱好，两人在严酷的军旅生活中建立了深厚的跨级友谊，经常在闲暇时刻讨论特区的亚人种与日本动漫文化。"
    },
    "佩露西亚": {
      "nature": "恋人、守护对象、初恋",
      "description": "佛马尔家的猫种亚人女仆。仓田对她一见钟情，为了保护佩露西亚，他不惜在撤退战中独自留在危险的战场或采取越权行动，展现了硬汉的一面。"
    },
    "栗林志乃": {
      "nature": "战友、互相吐槽的对象",
      "description": "同为第三侦察队的精锐，仓田经常被战斗狂栗林的高压气场压制，但在战场上是互相信任的后背。"
    },
    "富田章": {
      "nature": "战友、兄长般的前辈",
      "description": "在多次侦察行动中共同出生入死，富田对其稳健的驾驶技术非常信赖。"
    },
    "狹間浩一郎": {
      "nature": "上级指挥官",
      "description": "虽然军阶差距巨大，但作为第三侦察队的一员，仓田的行动一直处于狭间的全局指挥之下。"
    }
  }
}

