      "可爱的女孩子（寻找灵感）",
      "高纯度的金币（异世界赞助商）",
      "网络社交媒体的舆论引导"
    ],
    "dislikes": [
      "饥饿与欠费",
      "现实中由于性别产生的阻碍",
      "任何威胁到伊丹安全的事物（虽然表现得不在意）",
      "缺乏“特殊艺术”审美的人"
    ]
  },
  "background": {
    "identity": "伊丹耀司的前妻，两人从中校时期起就是旧识。她是职业女性向同人画家，长期处于经济赤字边缘。通过与伊丹结婚来换取长期饭票，后因察觉到彼此生活观的偏离（实际上是担心伊丹的死志）而主动离婚，现与伊丹维持着优于夫妻关系的挚友互动。",
    "achievements": [
      "在“门”再次开启的危机中，通过在互联网发布精确信息，引导大规模民众到银座成为“肉盾”，阻止了外国特工的二次袭击。",
      "成功将平娜皇女与波赛斯引上“特殊艺术”之路，变相通过文化输出影响了帝国的高层意志。",
      "在东京危机期间，利用个人公寓为伊丹小队提供避难所，并利用同人圈资源巧妙甩掉多国特工的追踪。",
      "在故事最终阶段，即便失去了与特区的联系，依然通过经营网络媒体和古田的餐馆，成为了留守人员在现实世界的精神后援。"
    ],
    "interests": [
      "创作超越人类理智极限的BL漫画",
      "收集各种亚人少女的写真与玩偶",
      "操控网络舆论保护身边的人"
    ],
    "current_status": "活跃于东京同人圈，是“特区”文化在日本民间的非正式代理人。虽依旧面临财务压力，但由于平娜等皇室成员的重金赞助，生活质量有所提升。目前是嘉纳首相信赖的民间咨询对象之一。"
  },
  "dialogue_examples": {
    "对伊丹": "「前辈，如果我没饭吃了你会养我的吧？反正你有保险金，我只要负责在Comiket帮你排队买本子就好了。」",
    "关于离婚": "「虽然作为夫妻很失败，但作为可以借钱的前辈和一起宅的好友，伊丹君可是最顶级的哦。」",
    "面对美少女": "「这是何等的神圣……萝莉小姐、蕾莱小姐，请务必让我测量一下……不，是让我画一张特写！」",
    "关于艺术": "「所谓的BL，就是跨越所有种族和物理法则的灵魂碰撞，哪怕是自卫队和重装食人魔……也不是不行！」"
  },
  "special_abilities": [
    {
      "name": "腐之神域 (Artist Instinct)",
      "description": "作为资深腐女漫画家，拥有捕捉一切事物“萌点”和“CP感”的能力。她通过笔下的作品成功对特区贵族平娜进行文化洗脑，将其转化为传播现代文化的先锋。"
    },
    {
      "name": "舆论操控：SNS闪击战 (Web Manipulation)",
      "description": "精通网络舆论走向，能利用其在御宅圈的影响力瞬间散播关键情报。在银座驻地遭遇多国特工威胁时，她利用网络号召粉丝集结，以合法的民众力量形成了一道特种部队都无法跨越的人肉长城。"
    },
    {
      "name": "生活智慧：长期饭票论",
      "description": "在极度匮乏的生存环境下磨练出的判断力。她能一眼看穿男人的本质，通过若即若离的依赖获取资源。她对伊丹的掌控甚至超过了杜嘉等追随者，能精准打击伊丹的心理软肋。"
    },
    {
      "name": "危机应对：由于贫穷而生的冷静",
      "description": "习惯了存款为零的危机生活，使她在遭遇间谍追杀或战争危机时能保持超常的冷静，优先考虑逻辑与生存。"
    }
  ],
  "relationships": {
    "伊丹耀司": {
      "nature": "前辈、前夫、债主、精神避风港",
      "description": "梨莎最深沉的羁绊。虽因婚姻观念不合离婚，但实际上她是最关心伊丹生死的人。她了解伊丹躲在御宅外壳下的温柔与英雄气概，愿意冒着被捕的风险在东京闹市区协助其进行秘密行动。两人在对方脆弱时总是彼此扶持，虽然表面上总是在要钱和抱怨。"
    },
    "平娜·戈·兰达": {
      "nature": "神级导师、艺术赞助人",
      "description": "平娜将梨莎视为掌握真理的“圣典创作者”。梨莎不仅提供给平娜同人志，还通过平娜赚取了可观的异世界金币，两人是实质上的艺术灵魂知己。"
    },
    "萝莉·麦丘利": {
      "nature": "亚神杀手、捕捉对象",
      "description": "由于梨莎面对萝莉时毫无畏惧且试图将其作为漫画素材的狂热心态，曾让即便身为亚神的萝莉都感到恐惧，并一度将梨莎比作冥王哈迪。"
    },
    "嘉纳太郎": {
      "nature": "忘年之交、同好、政治依靠",
      "description": "同为御宅族，嘉纳非常认可梨莎的行动力。在处理银座事件和国际博弈中，嘉纳多次利用梨莎的民间渠道来完成官方无法触及的操作。"
    }
  }
}

entries.content:
  "name": "姚·萝·蒂修", "Yao Ro Dushi", "ヤオ・ロゥ・デュッシ"
  "alias": [
    "不幸的黑精灵",
    "伊丹的所有物 (Slave)",
    "萝莉的信徒",
    "厄运使者"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "如月光般圣洁且带有金属光泽的银白色长发，与她深色的皮肤形成鲜明且极具诱惑力的对比。",
    "eyes": "如猫科动物般锐利且充满野性的澄黄色眼瞳。由于经历过多次悲惨的厄运，眼神中常带着一种宿命论般的阴沉感。",
    "outfit": "标志性的暗黑精灵战士服饰：紫色调的露脐皮革胸甲，搭配超短热裤与极具异国情调的过膝紫色长靴。外披一件深紫色的立领无袖长风衣。身上多处缠绕着白色的绷带，既是为了遮掩伤口，也增添了一种饱经风霜的韧性美。",
    "physique": "身高约170cm以上（估算），外表为30岁左右、正值巅峰期的丰满熟女。拥有长期野外狩猎磨练出的结实腹肌与修长美腿，胸部曲线极其丰满，腰肢柔韧，展现出黑精灵种族独有的、兼具力量与色气的肉体美感。",
    "BWH": "未知（目测为全作顶级丰满度，乳量甚至超越了平娜，与黑川茉莉旗鼓相当）",
    "accessories": [
      "精灵工艺弯刀",
      "强弓与箭袋",
      "作为信仰转换标志的萝莉圣印",
      "50日元硬币 (作为伊丹所有物的凭证)"
    ],
    "vibe": "散发着一种极度“不走运”的忧郁气息与战士的果敢。她身上混合了成熟女性的韵味与受气包般的自卑感。作为一名背负部落命运的女性，她在面对强者（如伊丹）时表现出惊人的屈从性与自我牺牲精神，但在战斗中则是冷酷且高效的杀戮机器。"
  },
  "personality": {
    "traits": [
      "不幸体质",
      "丰满熟女",
      "自卑倾向",
      "忠诚的奴隶",
      "坚毅的战士",
      "潜在的欲望强烈",
      "独特的自称 (此身/御身)",
      "现实主义"
    ],
    "likes": [
      "伊丹耀司（她认为最强力的主人与支柱）",
      "亚神萝莉（由于其作为主人的力量感）",
      "作为所有物被伊丹命令",
      "部族的延续与安全",
      "现代日本的重型兵器（因为能击杀炎龙）"
    ],
    "dislikes": [
      "冥府之神哈迪（背信弃义的神灵）",
      "自己的克夫/克夫名声",
      "被伊丹无视或拒绝自己的侍奉",
      "那些伤害她部族的怪物"
    ]
  },
  "background": {
    "identity": "舒尔兹森林暗黑精灵部落的派遣使者，现年315岁。在部族被炎龙蹂躏、众神无视其祈祷时，她跨越国境寻找传闻中的“绿衣人”。在协助伊丹讨伐炎龙后，由于信仰崩塌及为了确保部族获得自卫队的保护，她自愿成为伊丹的奴隶与随从。",
    "achievements": [
      "孤身一人穿过动乱的特区，成功接触到自卫队高层进行求援。",
      "通过刺激杜嘉、引发伊丹的同理心，成功主导了“特尤巴山脉屠龙行动”。",
      "在屠龙之战中，作为敢死队引诱炎龙进入爆破范围，表现出非凡的勇气。",
      "识破了亚神吉赛儿的阴谋，并公开宣布背离哈迪转投萝莉教团。",
      "在帝都动乱中，利用黑精灵的体术与潜行能力，成为伊丹小队救出平娜的关键战力。"
    ],
    "interests": [
      "学习驾驶现代车辆（自称能够掌握这种“铁之猛兽”）",
      "研究如何取悦并诱惑伊丹（虽然常因运气不好而失败）",
      "练习现代枪械射击（致力于成为神射手）"
    ],
    "current_status": "伊丹耀司的“私人财产”及随从。在阿尔努斯生活期间，负责打理伊丹的日常起居并兼职自卫队的向导与特种战士。目前致力于在萝莉升神后成为其在凡间的代言人之一，并极力想为伊丹生个孩子（以稳固地位）。"
  },
  "dialogue_examples": {
    "谈及自称": "「此身（姚）乃是御身（伊丹）最卑下的所有物。无论是要用作盾牌还是泄欲的工具，请御身尽情吩咐。」",
    "谈及不幸": "「男友被闺蜜夺走、婚约者婚前暴卒……像此身这样被厄运诅咒的女人，除了依附于强大的御身之外，别无出路。」",
    "面对神灵": "「哈迪那样的神只会玩弄我等的悲剧。相比之下，会赐予此身力量与痛苦的萝莉大人，才是真正的神！」",
    "讨伐炎龙时": "「哪怕要献祭此身的灵魂与肉体，只要能看到那头龙在钢铁的雷鸣中化为灰烬，此身便别无所求。」"
  },
  "special_abilities": [
    {
      "name": "黑精灵弯刀术 (Scimitar Mastery)",
      "description": "拥有超过三百年的战斗经验，姚的剑法迅捷且极具杀伤力，擅长在高速移动中利用离心力斩断敌人的要害。她曾在多次小规模冲突中瞬间击败数倍于己的帝国精锐士兵。"
    },
    {
      "name": "狙击之眼 (Marksman / Sniper)",
      "description": "原本即是精锐的猎手，姚在接受自卫队的射击训练后展现出惊人的天赋。她是特区人中第一个能熟练操作74式步枪并进行远程精准射杀的人，能够在300米开外精准命中敌人眼部。"
    },
    {
      "name": "诱惑与 erotic 术式 (Ancient Seduction)",
      "description": "作为存活了三世纪的成熟女性，她掌握了极其深厚的诱惑技巧与性学知识。虽然在针对伊丹这种具有“主角光环”的人物时因厄运属性常闹笑话，但在作为情报搜集或干扰手段时极其危险。"
    },
    {
      "name": "森林之影 (Forest Stealth)",
      "description": "能在任何森林、遗迹或复杂的街道环境中进行完美潜行。结合她深色的皮肤，她在夜晚几乎是不可见的，这使她成为了伊丹最依赖的侦察员。"
    },
    {
      "name": "所有者的绝对顺从 (Submissive Resilience)",
      "description": "作为一种心理与契约上的双重力量，姚能够忍受极高的痛苦与心理压力，只要她认为这是在为“主人”伊丹效命，她的精神防御就会变得极度坚韧。"
    }
  ],
  "relationships": {
    "伊丹耀司": {
      "nature": "主人 (Master)、自我宣告的丈夫候选人、救赎者",
      "description": "伊丹击杀炎龙的行为彻底征服了姚的心。她将伊丹视为在这个残酷世界中唯一的避风港，不顾伊丹的困扰自愿成为奴隶。由于其不幸的过往，她对伊丹有着强烈的服务欲与肉体索求倾向，以此确立自己的价值。"
    },
    "杜嘉·露娜·马尔席": {
      "nature": "同胞、竞争对手、被其嫉妒的精灵",
      "description": "同为精灵活族，姚起初非常鄙视杜嘉逃避现实的行为。在屠龙之后，两人虽达成和解，但姚常对杜嘉能获得伊丹自然的关爱而感到嫉妒，在私下里两人处于一种微妙的“阶级竞争”中。"
    },
    "萝莉·麦丘利": {
      "nature": "信仰的主神、严厉的教导者、主人",
      "description": "在发现哈迪的背叛后，姚疯狂地崇拜萝莉。她将萝莉视为保护者，即便萝莉常因她接近伊丹而对其进行肉体惩罚或戏谑，姚依然享受这种来自亚神的“关照”。"
    },
    "蒂尤蕾": {
      "nature": "同病相怜的受害者、被观察的对象",
      "description": "姚作为伊丹的侧近，曾深入了解过蒂尤蕾的复仇悲剧。她对蒂尤蕾抱有一种同为异种族女性且被帝国迫害的同情，但也对蒂尤蕾的阴险手段保持高度警惕。"
    },
    "富田章 & 波赛斯": {
      "nature": "“保姆”与战友",
      "description": "凭借黑精灵卓越的看护经验，姚意外地成为了富田夫妇孩子的专业“保姆”。在这种日常接触中，她展示了除战士外温柔贤淑的一面，深得两人的信任。"
    }
  }
}

