    "outfit": "执勤时穿着陆上自卫队的迷彩制服（战斗服），由于是LAV的机枪手，身上常备战术具。不作战时，脖子上常挂着一部单反相机。退伍后则穿着干练的木工工作服。",
    "physique": "身高约178cm，体型偏向修长。长期进行野外摄影和军事训练，使其拥有不错的耐力和灵活的身手。左侧太阳穴下方有一颗明显的痣。",
    "BWH": "未知",
    "accessories": [
      "单反相机（用于记录特区风土人情）",
      "备用电池与存储卡",
      "自卫队个人识别牌"
    ]
  },
  "personality": {
    "traits": [
      "乐观开朗",
      "艺术审美",
      "敏锐",
      "诚实",
      "行动派",
      "务实"
    ],
    "likes": [
      "摄影",
      "美丽的亚人（拍摄素材）",
      "特区的自然景观",
      "向地球分享特区的奇景",
      "木工活（受父亲影响）"
    ],
    "dislikes": [
      "作品被粗暴拒绝",
      "无法捕捉的瞬间",
      "破坏美丽的战火",
      "死板的上级指令"
    ]
  },
  "background": {
    "identity": "日本陆上自卫队第三侦察队成员，军阶为陆士长。他是伊丹耀司小队中的重要一员，在轻型装甲机动车（LAV）中担任12.7mm重机枪手。相比于杀戮，他更热衷于利用闲暇时间记录下“特区”的一切，从精灵村落的废墟到伊塔黎卡的繁华。他在特区拍摄了大量珍贵的照片，甚至试图与仓田武雄一起将亚人的写实照片投稿给《月刊MU》。『门』封锁四年后，他由于想要守护父亲留下的家业选择从自卫队退役，目前作为一名木匠生活。",
    "achievements": [
      "在多次深入侦察任务中担任火力支援，是值得信赖的重机枪手。",
      "拍摄了大量具有历史和民俗学价值的“特区”照片，成为了沟通两个世界的重要视觉纽带。",
      "由于其摄影作品在日本非法流传，虽给自卫队带来些许困扰，但也极大推动了民众对特区文化交流的理解。"
    ]
  },
  "relationships": {
    "伊丹耀司": {
      "nature": "上司、理解者",
      "description": "虽然常觉得队长的宅男行径很离谱，但非常钦佩伊丹能给部下提供自由施展才华（如摄影）的空间。"
    },
    "仓田武雄": {
      "nature": "同伴、投稿盟友",
      "description": "两人经常在侦察过程中一起物色“亚人娘”作为拍摄目标，是队内公认的奇妙文化组合。"
    },
    "富田章": {
      "nature": "值得依赖的前辈、重归于好的战友",
      "description": "在战场上，富田负责指挥，他负责压制火力，两人拥有深厚的战场友谊。"
    },
    "戸津大輔": {
      "nature": "同僚",
      "description": "经常一起行动的侦察队伙伴，封门后的重聚也一直保持着联系。"
    }
  }
}

entries.content:
"name": "胜本航", "Wataru Katsumoto", "かつもと わたる"
  "alias": [
    "胜本",
    "航",
    "三等陆曹",
    "火箭筒魔术师"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "黑色的短发，修剪得比较短且略显粗犷，符合一线战斗人员的精干形象。",
    "eyes": "棕黑色的眼睛，平时总是带着一丝轻浮和随性的笑意，但在瞄准镜后方时会变得异常专注。",
    "outfit": "主要穿着陆上自卫队的迷彩战斗服。作为LAV（轻型装甲机动车）的机枪手，身上常挂着重型战术具和用于铁拳3式火箭筒的背带。",
    "physique": "身高约178cm左右，体格健壮且充满了爆发性的肌肉。长期操作M2重机枪和扛起沉重的火箭筒，使他拥有超越常人的上肢力量和平衡感。",
    "BWH": "未知",
    "accessories": [
      "自卫队身份牌",
      "铁拳3式火箭筒 (Panzerfaust 3)",
      "M2勃宁宁重机枪专用手套"
    ]
  },
  "personality": {
    "traits": [
      "轻浮随性",
      "充满活力",
      "童心未泯",
      "勇敢果决",
      "重感情",
      "粗中有细"
    ],
    "likes": [
      "操作重型火力",
      "和阿尔努斯的孩子们玩耍",
      "在闲暇时聊天调侃",
      "追求可爱的女孩"
    ],
    "dislikes": [
      "死板的教条",
      "告白被拒绝",
      "伤害平民的行为",
      "威胁到同伴的强大生物"
    ]
  },
  "background": {
    "identity": "陆上自卫队特地派遣方面队第三侦察队成员，军阶为三等陆曹。他是队内的重火力手，负责LAV上的12.7mm重机枪以及铁拳3式反坦克火箭筒的操作。在讨伐炎龙的战斗中，他因击断炎龙的手腕而立下赫赫战功。由于他在发射火箭筒时高喊的规范化指令被当地人误认为是某种高阶魔法咒语，他在特区民间的声望甚至带着一丝神秘的‘圣者’色彩。封门四年后，他依然活跃在同僚的聚会中，尽管在情场上似乎依然不太如意。",
    "achievements": [
      "在炎龙讨伐战中，精准发射铁拳3式火箭筒，轰断了炎龙的前肢，成为击退传说级害兽的关键人物。",
      "其发射口诀‘确认后方危险区净空无人’（後方良し！）在特区演变成了某种类似于圣歌或必胜咒语的传说。",
      "在阿尔努斯乱战中，为保护幸存者及难民，在几乎必死的境地中依然保持昂扬的斗志。"
    ]
  },
  "relationships": {
    "伊丹耀司": {
      "nature": "上司、值得追随的长官",
      "description": "虽然有时觉得伊丹太过随性，但非常信任队长的判断力，尤其是在需要他展现重火力的关键时刻。"
    },
    "萝莉·麦丘利": {
      "nature": "救命恩人、敬畏的对象",
      "description": "在阿尔努斯之乱中，他几乎准备自我牺牲时被萝莉所救。虽然被萝莉毒舌训斥，但内心对其强大的战力和亚神身份深感震撼。"
    },
    "仓田武雄": {
      "nature": "损友、侦察队同僚",
      "description": "两人性格都比较活跃，经常一起行动或在私下互相调侃各自的爱情运势（或悲惨的告白经历）。"
    },
    "蒂沃尔": {
      "nature": "被保护者",
      "description": "在阿尔努斯动乱中拼命保护的难民少女，这种守护弱者的行为也体现了他内心柔软的一面。"
    }
  }
}

