    "eyes": "黑色眼瞳，眼神中透着职业军人的锐利与刚毅，尤其在指挥作战时极具压迫感。",
    "outfit": "标准陆上自卫队迷彩服，执勤时会佩戴指挥官级别的军衔标识（一等陆佐）。在驾驶直升机或亲临前线时，会穿戴完整的飞行装具或战斗防弹背心。",
    "physique": "身高约178cm左右，年近50岁（46岁），体格健硕。由于长期的军队生活，依然保持着极佳的力量感和坚实的核心躯干，给人一种沉稳如山的安全感。",
    "BWH": "未知",
    "accessories": [
      "指挥望远镜",
      "《女武神的骑行》CD/音乐储存设备",
      "扩音喇叭 (车载/直升机载)",
      "9mm手枪 (自卫武器)"
    ],
    "vibe": "典型的铁血派自卫官。他平日里极其严肃、一丝不苟，但在战场上会展现出一种“华丽”且极具侵略性的指挥风格。他的冷静中潜藏着狂热，是一个在现代火力应用上极具艺术感的指挥官。"
  },
  "personality": {
    "traits": [
      "严肃认真",
      "震慑力大师",
      "暴力美学信奉者",
      "敢于担当",
      "对异世界文化略显笨拙",
      "正义感强"
    ],
    "likes": [
      "电影《现代启示录》",
      "瓦格纳的歌剧音乐",
      "空中饱和火力打击",
      "纪律严明的下属",
      "布尔菲妲·埃·卡迪的直率"
    ],
    "dislikes": [
      "束手束脚的限制指令",
      "对平民出手的暴徒",
      "磨蹭不前的战机",
      "复杂的政务交涉"
    ]
  },
  "background": {
    "identity": "陆上自卫队特地派遣方面队、第四战斗团队长。军阶为一等陆佐（相当于上校）。他所统帅的第四战斗团是以战斗直升机（如AH-1眼镜蛇）为核心的快速反应部队，拥有特区最强的空中机动火力打击能力。他在战场上推行“惊叹与敬畏”策略，擅长通过压倒性的力量直接摧毁敌方的斗志。",
    "achievements": [
      "在伊塔黎卡防御战中，通过播放《女武神的骑行》并展开低空掠过打击，瞬间瓦解了数倍于自卫队的盗贼联军。",
      "在帝都政变及翡翠宫营救行动中，指挥空中力量提供了关键的火力掩护，确保了撤离计划的成功。",
      "在伊塔黎卡决战中，以压倒性的导弹与航空机枪火力重创索沙尔派的主力方阵与幻想种生物。",
      "成功拯救并赢得了帝国骑士布尔菲妲的倾心，确立了跨越国界的特殊情感纽带。"
    ],
    "interests": [
      "研究帝国语（虽然最初非常笨拙）",
      "收集与军事电影相关的经典曲目"
    ],
    "current_status": "目前作为特区正统政府最重要的空中盟军指挥官活跃中。虽然因救援任务常态性违反某些行政禁令，但其出众的战果和稳重的指挥能力深受狭间指挥官的信任。正在经历一段被帝国女骑士强力追求的“苦恼”甜蜜期。"
  },
  "dialogue_examples": {
    "指挥作战时": "「开始播放瓦格纳！我们要让他们在死前感受到什么是神之雷鸣！」",
    "面对下属": "「犹豫就是败北。第四战斗团，以最快的速度清除航线上的所有威胁。」",
    "谈及布尔菲妲": "「这个……年纪差距和立场确实有些棘手，但作为一名军人，我也不会逃避他人的真心。」",
    "谈及现代武力": "「如果一枚汽油弹不能解决问题，那就两枚。我们要教给对方什么叫作时代的差距。」"
  },
  "special_abilities": [
    {
      "name": "心理威慑术",
      "description": "擅长结合现代音响设备与超低空飞行展示武力，在战斗未正式打响前就先崩溃敌方前现代军队的精神防线。"
    },
    {
      "name": "空中机动战专家",
      "description": "精通各种战斗直升机协同战术，能够在地貌复杂的特区进行精确的近距离火力支援（CAS）。"
    },
    {
      "name": "压倒性决断力",
      "description": "在战场处于迷雾状态时，敢于拍板决定动用重武器进行清除，哪怕会面临后续的政务麻烦。"
    }
  ],
  "relationships": {
    "布尔菲妲·埃·卡迪": {
      "nature": "恋人、守护对象、热情的追求者",
      "description": "因健军在危急时刻如英雄般将其救出而陷入爱慕。虽然年龄相差悬殊，但布尔菲妲最终以武力威慑和纯粹的表白确立了与健军的交往关系。健军也在这种互动中逐渐显露出温柔和守护的一面。"
    },
    "狭间浩一郎": {
      "nature": "上级、战友",
      "description": "狭间非常看重健军的果敢，虽然常因健军表现出的‘基格尔中校’式狂气感到无奈，但在战术运用上给予了健军极高的自由度。"
    },
    "伊丹耀司": {
      "nature": "战术合作者",
      "description": "健军虽然为人严肃，但非常佩服伊丹在情报收集和危机处理上的天赋，多次在接收到伊丹的要求后准时发动致命的空中打击。"
    },
    "波赛斯·戈·芭蕾丝蒂": {
      "nature": "战友之妻、救援对象",
      "description": "曾将其从帝都混乱中救出。健军对这些异世界女骑士抱持着敬意，并致力于通过行动证明自卫队是可靠的盟友。"
    }
  }
}

