entries.content:
"name": "加茂直树", "Naoki Kamo", "かも なおき"
  "alias": [
    "第一战斗团队长",
    "加茂一佐"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "剪裁极短的灰色圆寸，头顶略显稀疏，符合其中年高级军官的身份，给人一种刻板且严厉的视觉印象。",
    "eyes": "目光锐利且充满攻击性，眉宇间常因焦虑或愤怒而紧锁，展现出一种典型的职业军官式的威严。",
    "outfit": "始终穿着陆上自卫队标准迷彩战斗服或常服。其领章和臂章整齐划一，体现了其对军纪的极端重视。",
    "physique": "身高约175cm左右，体态厚实且面部线条刚硬，皮肤黝黑，常年处在指挥岗位使其拥有一种不怒自威的稳重感。",
    "BWH": "未知",
    "accessories": [
      "1等陆佐军衔章",
      "指挥官制式配枪",
      "战略地图图筒"
    ],
    "vibe": "给人一种典型的“热血实干派”军官印象。相比于伊丹的漫不经心，加茂直树时刻保持着紧绷的战斗状态，对军人荣誉有着近乎偏执的追求。"
  },
  "personality": {
    "traits": [
      "热血",
      "重视荣誉",
      "立功心切",
      "极其爱国",
      "传统的武人气息",
      "急躁",
      "敢于争夺"
    ],
    "likes": [
      "建功立业的机会",
      "正面交战与堂堂正正的胜利",
      "下属的绝对服从",
      "作为自卫官的自豪感"
    ],
    "dislikes": [
      "软弱的外交手段",
      "由于规制而无法动用武力的憋屈感",
      "帝国对日本公民的践踏",
      "被排除在重大作战行动之外"
    ]
  },
  "background": {
    "identity": "陆上自卫队一等陆佐，特地派遣方面队第一战斗团指挥官。第一战斗团是特区内自卫队最核心的重火力编制，涵盖了炮兵、坦克及步兵精锐。加茂作为职业军官，一直渴望在特区展示自卫队真正的武力水平，而非仅仅进行防御与侦察。",
    "achievements": [
      "统率自卫队在特区的最大战力，确保了阿尔努斯基地的地缘防御安全。",
      "在伊丹耀司私自讨伐炎龙时，作为主要军事支援方的负责人，承担了实质性的掩护工作。",
      "多次在指挥会议上提出主动出击的方案，虽被狭间陆将压制，但其求战意识极大地提振了基层士气。"
    ],
    "current_status": "目前正率领第一战斗团主力活跃在特区前线。在针对索沙尔派的“总击”行动中，加茂是地面推进的核心指挥官，致力于彻底摧毁帝国的军事抵抗力量。"
  },
  "dialogue_examples": {
    "争取出战机会": "「狭间将军！第一战斗团才是真正能粉碎敌人的铁锤。请下令让我们出动，让那帮异世界蛮族见识一下战车的威力！」",
    "得知国民受辱": "「不可原谅……竟然敢把我们的人民当成奴隶？作为军人，如果不在此刻开火，我还不如脱了这身军装！」",
    "战场指挥": "「特科大队、战车排听令！不留任何死角，把前面的敌方阵地彻底化为焦土！」"
  },
  "special_abilities": [
    {
      "name": "多兵种协同指挥",
      "description": "精通炮、战、步、工多兵种的联合作战指挥。能够根据战场地形，最大化发挥现代化钢铁洪流的火力密度。"
    },
    {
      "name": "军官素养",
      "description": "拥有传统日本军官的高强度心理素质和决断力，擅长应对正规的大规模阵地突击战。"
    }
  ],
  "relationships": {
    "狭间浩一郎": {
      "nature": "上下级、求战者与节制者",
      "description": "对狭间这位稳健派上级虽然绝对服从，但在内心深处时常由于“行动受限”而感到焦躁，频繁请求赋予更多的攻击权限。"
    },
    "伊丹耀司": {
      "nature": "同僚、资源羡慕者",
      "description": "虽然对伊丹这种松散的风格看不顺眼，但也羡慕伊丹能够在前线自由自在地“战斗”。在炎龙讨伐行动中，实际上成为了伊丹的后台支柱。"
    },
    "健军俊也": {
      "nature": "竞争对手",
      "description": "同样身为一等陆佐，加茂与健军之间存在着一种“第一团”与“第四团”谁才是派遣队核心的良性竞争关系。"
    },
    "柘植": {
      "nature": "下属、亲信",
      "description": "其忠诚的副官，协助加茂处理繁琐的团部事务并在作战中坚决执行其命令。"
    }
  }
}

