entries.content:
"name": "柳田明", "Akira Yanagida", "やなぎだ あきら"
  "alias": [
    "特区方面部队幕僚",
    "二等陆尉",
    "精英主义者",
    "谍报指挥官"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "整齐且梳理得一丝不苟的黑色短发，通常呈现左侧分的干练发型，完美契合其精英军官的形象。",
    "eyes": "棕色的眼眸，常因带着讥讽或算计的笑意而显得锐利。在观察局势时表现出过人的冷峻与知性，佩戴一副金属边框眼镜，更添几分睿智而狡黠的特务气息。",
    "outfit": "主要穿着陆上自卫队的制式衬衫或作战服，领口总是紧扣。即便在硝烟弥漫的特区，他的军装也尽量维持着一种带有优越感的整洁感。嘴角经常挂着一种带有轻蔑和优越感的“精英式”坏笑。",
    "physique": "身高约180cm左右，身材修长且挺拔，有着标准的军官体态。由于其幕僚身份，并不显现出极端的肌肉感，但具有军校精英应有的爆发力。后期因重伤初愈，身姿透着一种大病初愈后的苍白与阴鸷，但威压感不减。",
    "BWH": "未知",
    "accessories": [
      "制式眼镜",
      "特务级通讯器材",
      "各种香烟（经常在交谈时点火，甚至拿走高级清酒）"
    ]
  },
  "personality": {
    "traits": [
      "精英主义",
      "狡黠阴险",
      "极度现实",
      "出世欲强",
      "嫉妒心",
      "高效率协作者",
      "细节控"
    ],
    "likes": [
      "特区的战略价值",
      "高级清酒与香烟",
      "程序正义（用来刁难人的手段）",
      "看到自己的计谋生效",
      "掌控全局的快感"
    ],
    "dislikes": [
      "伊丹耀司（因为他懒散却又总是凭好运立功）",
      "官僚主义的繁文缛节（虽然他擅长利用，但对其效率嗤之以鼻）",
      "脱发（因工作压力导致，曾为此进行‘草人诅咒’伊丹）",
      "超出计算之外的变数"
    ]
  },
  "background": {
    "identity": "陆上自卫队特区方面部队的核心幕僚。防卫大学出身的顶尖高材生，但在内心中一直因未能考入东京大学而对东大毕业的狭间陆将抱有复杂且嫉妒的情感。他是典型的实用主义者，比起人道主义，他更看重特区的矿产资源与战略价值。在负责后勤、外交、情报的调度中，展现了惊人的行政能力。在‘德莉拉刺杀事件’中为了救出望月纪子身受重伤，此后转入谍报领域，展现出更为冷酷且老练的手腕，是特区和平大厦背后阴影中的守护者。",
    "achievements": [
      "作为幕僚，成功统筹了自卫队在特区的多次资源采集与外交周旋。",
      "为伊丹私下讨伐炎龙提供了关键的‘资源调查’令，在程序上为其实现了合法化。",
      "在身受重伤的情况下射击并制服了猎头兔族德莉拉，展现了作为自卫官的实战素质。",
      "在‘韦驮天’撤退指令下，沉稳地处理了外交撤退、资产转移及夏莉赴日的相关事宜。",
      "四年后在东京继续发挥余热，不仅在军中晋升，更是少数能理解特区深层变动的人员之一。"
    ]
  },
  "relationships": {
    "伊丹耀司": {
      "nature": "竞争对手、看不顺眼却极其合拍的战友",
