entries.content:
"name": "江田岛五郎", "Edajima Goro", "えだじま ごろう"
  "alias": [
    "海上自卫队二等海佐",
    "特地担当统括官",
    "意志力的化身",
    "模型狂魔",
    "江田岛司令"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "整齐向后梳理的灰色短发，由于常年深思，发际线清晰且带有某种知性的学者气质，但在海军制服的衬托下更显干练。",
    "eyes": "隐藏在眼镜后的细长双目，总是在分析情报时透出锐利的光芒。尽管平时表现得比较温和，但下达决断时有着不容置疑的威严。",
    "outfit": "主要穿着海上自卫队标志性的夏季白色立领制服或冬季黑色常服。制服一尘不染，胸前挂有象征荣誉的略绶。在潜艇内部则会穿着更加实用的深蓝色作战服。",
    "physique": "身高约175cm左右，体态匀称，完全看不出中年人的赘肉。其姿态中透出一种如钢铁般坚韧的柔韧性，举手投足间展现出作为精英士官的良好修养。",
    "BWH": "未知",
    "accessories": [
      "精密的海图指针",
      "作为心理寄托的微缩船模",
      "银色边框的近视眼镜"
    ],
    "vibe": "给人一种如同深海潜艇般“静水流深”的压抑与可靠感。他代表了海上自卫队在特区的最高情报与战术水平，是一位能在理智与狂气之间游走，并利用逻辑彻底击溃敌人的战术大师。他那关于“意志力”的教条令人印象深刻。"
  },
  "personality": {
    "traits": [
      "极度理智",
      "御宅族特有的执着",
      "腹黑阴险（外交层面）",
      "重视后辈",
      "绝对的意志力",
      "爱国者",
      "理论派"
    ],
    "likes": [
      "帆船及现代军舰模型",
      "极致的战术模拟",
      "挖掘有潜力的部下（如德岛）",
      "道理的累积",
      "特区的海洋奥秘"
    ],
    "dislikes": [
      "不讲逻辑的蛮干",
      "对日本国家利益的侵犯",
      "损毁精密的模型",
      "因官僚怠慢导致的资源浪费"
    ]
  },
  "background": {
    "identity": "日本海上自卫队派遣至“特区”的实权人物之一，担任情报业务群·特地担当统括官。在自卫队尚未在特区设立海军基地时，他以驻外武官身份活跃，并因其在办公桌摆放军舰模型而被称为“特区的奇人”。在《Weigh Anchor（拔锚篇）》中，他成为核心主角之一，不仅在潜艇战中展现了超越神迹的指挥艺术，更在复杂的多国博弈中，为日本确立特区海洋主权奠定了坚实的基础。他坚信御宅族的执着即是意志力的最高体现。",
  },
  "relationships": {
    "德岛甫": {
      "nature": "师徒、绝对信任的拍档、毒舌的对象",
      "description": "虽然经常吐槽德岛的厨师性格，但非常看重德岛在极端环境下的应变能力和纯粹的意志。他是德岛从一个单纯的厨师成长为一名优秀特战员的引路人。"
    },
    "伊丹耀司": {
      "nature": "志趣相投的后辈、御宅族盟友",
      "description": "江田岛对伊丹这种“只要努力就能活得自由”的处世态度抱有敬意。由于同为资深御宅族，两人在解决特区重大危机时常有跨军种的默契配合。"
    },
    "普莉梅拉": {
      "nature": "政治保护对象、考察中的女王候補",
      "description": "起初将普莉梅拉视为烫手山芋和政治筹码，但在共同经历生死海战后，开始有意地通过自卫队的影响力来引导她成为能够稳定亚维恩局势的领导者。"
    },
    "狭间浩一郎": {
      "nature": "职场同僚、战略共谋者",
      "description": "两人在特区的高层决策中常常一唱一和。江田岛利用海自的特殊性弥补了陆自难以介入的海上情报空缺，深受狭间的信任。"
    }
  }
}

