"name": "驹门英世", "Hideyo Komakado", "こまかど ひでよ"
  "alias": [
    "公安的狐狸",
    "防卫省的引导者",
    "闪腰特工"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "黑色乱发，带有那种因忙碌而无暇打理的蓬松感。在漫画版中则表现为紧贴头皮的鬓角油头。",
    "eyes": "深邃的黑色眼瞳。平时总是一副睡眼惺忪、漫不经心的样子，但当进入职业状态时，目光会瞬间变得如同利刃般锐利，充满审视感。",
    "outfit": "标志性的穿搭是略显褶皱的米色战壕风衣（Trench Coat），内搭深色西装和棕色领带。这种酷似“神探可伦坡”的打扮让他看起来更像一个落魄大叔而非精锐特工。",
    "physique": "中等身材的中年男性。由于长期从事案头与潜伏工作，并不显强壮。由于在银座事件护卫任务中强行尝试举起萝莉的斧枪导致腰部严重损伤（椎间盘突出），后期长期拄着手杖，身形消瘦了不少。",
    "BWH": "未知",
    "accessories": [
      "公安警察身份证件",
      "步行辅助用手杖 (后期使用)",
      "香烟"
    ]
  },
  "personality": {
    "traits": [
      "狡黠多谋",
      "尽忠职守",
      "深藏不露",
      "现实主义",
      "观察力极其敏锐",
      "偶尔脱线 (如闪到腰)",
      "对志同道合者的宽容"
    ],
    "likes": [
      "伊丹耀司 (欣赏其那种隐藏在松散下的精明)",
      "国家利益 (绝对的爱国者)",
      "看穿他人的阴谋",
      "高效的情报工作",
      "安静的观察点"
    ],
    "dislikes": [
      "外国情报机构的渗透 (美、中、俄等)",
      "官僚主义带来的效率低下",
      "沉重到离谱的异世界武器 (身体记忆的痛苦)",
      "破坏社会稳定的暴力抗议"
    ]
  },
  "background": {
    "identity": "原本隶属于警视厅公安部的高级官员，因“门”的出现被调往防卫省情报本部担任要职，后重返公安部担任负责人。他是自卫队与特区人员在日本境内活动的非正式‘监护人’与屏障。他负责在复杂的国际政治博弈中保护蕾莱一行人，利用反间谍手段挫败了多起绑架和暗杀计划。虽然在生理上因亚神武器遭受了永久性损伤，但他依然凭借其卓越的脑力掌控着日本国内的防谍战线。",
    "achievements": [
      "在伊丹一行首次访日期间，通过部署大量诱饵车队成功瓦解了多国特工的追踪计划。",
      "一眼识破外国情报人员伪装的平民，并精准预判了袭击的时间点。",
      "即使在住院期间，依然通过远程指挥完成了对银座附近潜伏敌特的收网行动。",
      "在后续的‘开门实验’和‘银座动乱’中，作为公安首脑协助嘉纳大臣和自卫队控制局势。",
      "利用非法手段获取的情报，成功帮助日本政府在与多国的谈判中占据主导地位。"
    ]
  },
  "relationships": {
    "伊丹耀司": {
      "nature": "惺惺相惜、由于性格相近而产生的深厚信任、某种意义上的‘宅友’",
      "description": "驹门非常看重伊丹，因为他在伊丹身上看到了和自己一样的‘伪装成懒散者的精英’质感。在伊丹数次违反规定或遭遇调查时，他都在职权范围内提供了最大程度的便利与掩护。"
    },
    "萝莉·麦丘利": {
      "nature": "敬畏的对象、‘毁掉自己腰部’的源头",
      "description": "对身为亚神的萝莉保持着极高的礼遇，同时也因当年因好奇想拎起她的巨型斧枪而闪到腰一事留下了深刻的心理阴影和肉体后遗症。"
    },
    "嘉纳太郎": {
      "nature": "上级、政治盟友",
      "description": "作为防卫省和公安部的桥梁，他与嘉纳配合默契，是嘉纳在特区政策中处理‘脏活’与‘硬活’的首选干将。"
    },
    "蕾莱·拉·列娜": {
      "nature": "保护对象、作为‘开启者’的关键目标",
      "description": "驹门深刻理解蕾莱对日本国家安全的双重意义——既是奇迹的钥匙，也是诱发战争的炸药。他竭尽全力保护其不落入中国等势力手中。"
    }
  }
}

