"name": "古村崎哲朗", "Tetsuro Komurazaki", "こむらざき てつろう"
  "alias": [
    "独立记者",
    "特地报道先驱",
    "顽固的老头",
    "全共斗的幸存者"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "灰白相间的短发，显得有些凌乱，透着一种不修边幅的媒体人气质。",
    "eyes": "深陷的眼窝中透着精明且充满批判性的目光，习惯于透过镜头和眼镜审视世界。",
    "outfit": "典型的战地记者装束，多口袋的摄影背心，磨损严重的工装裤，胸前常挂着数反单反相机。在特区调研时，会披上一件挡风的旧风衣。",
    "physique": "年过五十，身材瘦削但依然保持着长年在外跑新闻的干劲，步履间虽不具备军人的矫健，却有着新闻人的顽强。",
    "BWH": "未知",
    "accessories": [
      "单反相机（数字/胶片混合使用）",
      "录音笔",
      "采访笔记本"
    ]
  },
  "personality": {
    "traits": [
      "固执偏颇",
      "怀疑主义",
      "极度缺乏军事常识",
      "自命不凡",
      "反权威倾向",
      "骨子里的新闻人自尊"
    ],
    "likes": [
      "所谓的“独家真相”",
      "挖掘政府与自卫队的丑闻",
      "新闻自由",
      "烟草（在采访间隙）",
      "挑战既有的权力结构"
    ],
    "dislikes": [
      "政府对信息的管控",
      "大财团主导的商业媒体",
      "军事组织的“傲慢”（实为由于其军事素养低下的误解）",
      "被当成需要保护的对象"
    ]
  },
  "background": {
    "identity": "一名坚持以“少数派”视角观察世界的独立记者。学生时代曾是全共斗的一员，有着深刻的反体制色彩。为了寻求不被政府和广告商过滤的报道，他深入特区采访。虽然因缺乏基本的军事素养而闹出不少笑话（如误认为伞兵待机是偷懒），甚至给护卫他的自卫官添了不少麻烦，但他依然秉持着将情报传递给民众的尊严，在关键时刻亦能摒弃成见协助他人突破信息封锁。",
    "achievements": [
      "成功深入特区前线进行第一手影像采集。",
      "在特区遭遇怪异扫荡时虽身处险境，仍记录了珍贵的战场实况。",
      "在“门”出现崩坏危机期间，协助栗林菜菜美突破情报管制，通过非正式渠道将真实消息扩散至民间。"
    ]
  },
  "relationships": {
    "栗林菜菜美": {
      "nature": "竞争对手、后辈同行、关键时刻的共事者",
      "description": "虽然由于报道立场不同而经常发生争执，但在面对政府隐瞒真相时，他能大方地提供情报渠道，表现出老牌新闻人的风骨。"
    },
    "伊丹耀司": {
      "nature": "采访对象、反权威观察的目标",
      "description": "最初认为伊丹不过是自卫队包装出来的虚假英雄，并在报道中极尽冷嘲热讽。但随着采访深入，不得不对其在乱局中的生存能力和决断力产生复杂的评价。"
    },
    "栗林志乃": {
      "nature": "护卫、被麻烦的对象",
      "description": "在特区采访期间由其贴身护卫，古村崎的任性要求和缺乏常识的行动曾数次让她大发雷霆，甚至导致队伍陷入战术陷阱。"
    },
    "富田章": {
      "nature": "护卫",
      "description": "与栗林志乃共同担任护卫工作，作为常识人的富田经常需要平衡古村崎的荒诞要求与实战需求之间的矛盾。"
    }
  }
}

