entries.content:
"name": "栗林菜菜美", "Nanami Kuribayashi", "くりばやし ななみ"
  "alias": [
    "独立记者",
    "特区报道先驱",
    "栗林在线新闻台负责人",
    "志乃的妹妹"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "棕色长发，发色与姐姐志乃一致，但发型通常更为柔和。在从事记者工作时，显得知性而有亲和力。",
    "eyes": "棕色眼瞳，清澈且富有求知欲。面对摄像机时有着新闻从业者的坚定眼神。",
    "outfit": "早期常穿白色针织衫搭配黑色外套，胸前挂着专业相机或手持麦克风。由于其极其惊人的上围，普通的职场服装往往也会被勾勒出极具视觉冲击力的曲线。",
    "physique": "身高约160cm，20岁左右。虽然性格与暴力的姐姐截然相反，但在体态上完美继承了栗林家遗传的丰满基因——拥有极其傲人的巨乳。肤色白皙，透着一股大都市年轻女性的精致感。",
    "BWH": "未知（目测与姐姐栗林志乃相当，处于全作顶级水平）",
    "accessories": [
      "新闻采访用麦克风",
      "专业单反相机",
      "录音设备"
    ]
  },
  "personality": {
    "traits": [
      "性格温和",
      "执着正义",
      "求真务实",
      "初期羞怯",
      "后期坚毅",
      "行动派"
    ],
    "likes": [
      "挖掘并传递真相",
      "网络新闻的自由度",
      "姐姐栗林志乃（虽然害怕她的暴力）",
      "伙伴望月纪子",
      "公正的舆论环境"
    ],
    "dislikes": [
      "媒体对真相的歪曲",
      "肥田木等人的舆论操控",
      "官僚主义对信息的封锁",
      "姐姐毫无节制的暴力倾向"
    ]
  },
  "background": {
    "identity": "一名致力于追求真相的年轻记者，栗林志乃的亲妹妹。最初在主流媒体工作，因在银座偶然捕捉到重返特区的自卫队一行并录制了姐姐志乃的“反绑架宣言”而名声大噪。由于对主流媒体受到政府和财团压力而进行的选择性报道感到极度幻灭，她与特区归来的难民望月纪子联手创办了独立网络媒体。她深入特区一线，在“门”关闭前后的关键时刻，通过非官方渠道向民众揭示了真实的特区局势和国际阴谋，成为了连接地球民众与特区真相的桥梁。",
    "achievements": [
      "在银座事件现场捕捉到姐姐志乃对多国特工绑架阴谋的公开 denounce。",
      "在特区进行实地采访，记录了大量第一手人文与军事资料。",
      "与望月纪子合作经营“事实提供者”网站，成功对抗了肥田木等人的信息管制。",
      "揭露了森田首相与外国势力的幕后交易，间接推动了政坛洗牌。",
      "在“门”关闭四年后，已成长为日本顶尖独立新闻工作室的领军人物。"
    ]
  },
  "relationships": {
    "栗林志乃": {
      "nature": "亲姐姐、采访对象、由于性格反差而产生的敬畏与羁绊",
      "description": "菜菜美是家中唯一敢正面指出志乃暴力倾向的人，虽然常常因此被蹂躏。姐妹俩在特区真相的揭露上达成了默契的“文武配合”。"
    },
    "望月纪子": {
      "nature": "最佳拍档、亲如姐妹的战友",
      "description": "两人共同创办并运营网站，由纪子提供特区第一手译文与情报，菜菜美负责影像制作与传播。她们的合作让大众得以绕过传统媒体看到真相。"
    },
    "古村崎哲朗": {
      "nature": "前辈、竞争对手、理念不同者",
      "description": "虽然古村崎经验丰富，但菜菜美更倾向于客观实录而非主观臆断，在报道立场上曾多次产生冲突，但最终在追求真相上殊途同归。"
    },
    "伊丹耀司": {
      "nature": "重要的采访目标、由于姐姐关系而建立的熟人",
      "description": "菜菜美曾多次尝试通过各种渠道深入挖掘伊丹的“废柴英雄”真面目，是她赋予了自卫队在民间独特的叙事形象。"
    }
  }
}

