entries.content:
"name": "望月纪子", "Mochizuki Noriko", "もちづき のりこ"
  "alias": [
    "“特区”平民翻译",
    "在线新闻播报员",
    "银座事件幸存者",
    "梅甘娜科（博客名）"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "黑色短发，呈现干练的波波头（Bob cut）造型，显得知性且柔和。",
    "eyes": "深邃的红褐色瞳孔，在经历创伤后一度显得忧郁无神，后期因投身事业而变得坚定且充满生命力。",
    "outfit": "初登场时由于奴隶身份，仅披着褴褛的布片或戴着项圈。获救后主要穿着日本现代服装或适合在阿尔努斯活动的休闲职场装。在从事记者与翻译工作时，通常会佩戴眼镜（Meganekko形象）。",
    "physique": "少女至二十代前半的体态，身材纤细，带着都市女性的精致。因曾遭受索沙尔的长期虐待和营养不良，肤色略显苍白，但在自卫队的照顾下逐渐恢复。右眼下方有时会因疲劳出现轻微黑眼圈。",
    "BWH": "未知",
    "accessories": [
      "奴隶项圈（已拆除）",
      "采访用笔记本与录音笔",
      "标志性的黑框眼镜"
    ]
  },
  "personality": {
    "traits": [
      "坚毅",
      "现实主义",
      "知性",
      "曾经消极（创伤后压力）",
      "强烈的正义感",
      "语言天赋",
      "勤奋"
    ],
    "likes": [
      "揭示“特区”的真实人文与社会",
      "与亚人建立友谊",
      "摄影与博客创作",
      "香烟（漫画设定）",
      "伊丹等救命恩人"
    ],
    "dislikes": [
      "帝国的奴隶制度",
      "皇太子索沙尔（极度恐惧且厌恶）",
      "主流媒体的虚假报道与偏见",
      "不负责任的谣言",
      "滥杀无辜的战争"
    ]
  },
  "background": {
    "identity": "原本是日本一名平凡的现代女性，在“银座事件”中被帝国侦察兵绑架至门的一侧。她是所有被绑架国民中命运最为凄惨的人之一：父母在袭击中丧命，家屋烧毁，恋人在矿山奴隶劳动中死于塌方，而她本人则沦为皇太子索沙尔的性奴隶，遭受了长期的身体与精神摧残。被伊丹救出后，曾因一无所有而陷入虚无主义的重度抑郁，甚至在德莉拉暗杀她时主动求死。被柳田救治后逐渐找回活下去的意义。利用被囚禁期间自学的一系列亚人语言和英语、法语天赋，成为了自卫队与国际媒体间的关键翻译官与独立新闻人。",
    "achievements": [
      "在被俘期间奇迹般地掌握了多种亚人语言。 ",
      "协助伊丹一行人完成与帝国最初的俘虏遣返谈判。",
      "在“门”世界建立高人气的真相博客，成功对抗了媒体对自卫队的妖魔化报道。",
      "在“门”关闭的四年间，成长为连接地球与“特区”最重要的在线播报员与首席翻译。 ",
      "作为民间观察者，记录了阿尔努斯从废墟到多元文化都市的演变。"
    ]
  },
  "relationships": {
    "伊丹耀司": {
      "nature": "救命恩人、崇拜对象、战友",
      "description": "伊丹在谒见厅为她挥向索沙尔的那一拳，是她生命重生的转折点。她对伊丹抱有极深的感激与绝对的信任。"
    },
    "柳田明": {
      "nature": "恩人、保护者、复杂的羁绊",
      "description": "柳田在德莉拉的利刃下救了她的命并因此身受重伤，这让她从一心求死的消极状态中觉醒，开始积极面对人生。"
    },
    "索沙尔·埃·凯萨": {
      "nature": "梦魇、施暴者、绝对的仇敌",
      "description": "纪子曾是他手中被随意凌辱的玩物。这种深刻的心理阴影直到索沙尔死亡和她建立新事业后才逐渐淡化。"
    },
    "栗林菜菜美": {
      "nature": "最佳合作伙伴、事业领路人",
      "description": "两人联手揭露特区真相。纪子提供第一手资料和翻译，菜菜美负责传播，共同打破了传统媒体的信息垄断。"
    },
    "古村崎哲朗": {
      "nature": "批判对象、竞争性同行",
      "description": "纪子对他那种带有偏见且缺乏实地考察的虚假报道极度反感，多次以亲身经历在公众面前打脸其报道内容。"
    },
    "蒂尤蕾": {
      "nature": "前主人家的侧近、间接的仇怨与救赎",
      "description": "曾作为索沙尔的玩物观察过蒂尤蕾的隐忍。虽然一度因蒂尤蕾策划暗杀自己而身陷险境，但也通过这一事件结识了柳田。"
    }
  }
}

