entries.content:
"name": "董德愁", "Dong Dechou", "とう とくしゅう"
  "alias": [
    "中華人民共和國主席",
    "董主席",
    "移民計畫發起者"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "整齊向後梳理的黑髮，略顯稀疏但被打理得極為體面，透出一種大國領導人的威嚴與老練。",
    "eyes": "隱藏在無框眼鏡後的細長雙眼，目光冷靜且具有極強的審視感，常年處於權力核心使其眼神中透著一種不怒自威的壓迫力。",
    "outfit": "正式場合穿著剪裁精良的深藍色或黑色中山裝、西裝，細節處一絲不苟，領帶色調穩重。這種穿著強化了他作為傳統與權威結合體的形象。",
    "physique": "身材中等，因長期從事高強度的政治活動而顯得有些疲態，但站立姿態依舊穩健。他的外貌與氣質讓人聯想到現實中的政治家，散發著務實與果敢的氣場。",
    "BWH": "未知",
    "accessories": ["精緻的鋼筆", "加密通訊設備", "無框眼鏡"],
    "vibe": "散發著一種典型的、務實且冷酷的官僚主義領袖氣息。他不僅是一個國家的象徵，更是一個龐大國家意志的執行者。在他的身邊，人們能感受到一種基於大國國力支撐的、不容置疑的自信與侵略性。"
  },
  "personality": {
    "traits": [
      "極度國家利益至上",
      "務實主義者",
      "野心家",
      "冷酷無情",
      "戰略眼光敏銳",
      "高效",
      "果斷"
    ],
    "likes": [
      "國家的能源安全",
      "領土與影響力的擴張",
      "高效的情報網絡",
      "可控制的局勢"
    ],
    "dislikes": [
      "人口膨脹導致的內部動盪",
      "日本對“門”的壟斷",
      "不聽使喚的代理人（如迪亞波）",
      "行動失敗後的政治風險"
    ]
  },
  "background": {
    "identity": "中華人民共和國最高領導人（主席）。他面臨著國內嚴峻的人口壓力和能源危機，因此將“特區”視為解決中國生存困境的終極聖地。他的目標極其狂野：將中國約一半的人口（約七億人）移民至特區，將那裡徹底轉化為“另一個中國”。為此，他不惜動用情報機構、派遣特務，甚至策劃武裝綁架行動以獲取情報，是推動國際干預“門”背後的關鍵推手。",
    "achievements": [
      "策劃了旨在綁架特區重要人物（平娜、杜嘉、蕾萊、蘿莉等）的祕密行動。",
      "與帝國皇子迪亞波達成暫緩“封門”的密約，試圖獲取永久性的特區通道。",
      "在特區內部扶植代理人並部署秘密情報站，滲透阿特蘭提亞等勢力。",
      "策劃“銀座紅旗計劃”，試圖通過非政府組織與武裝分子的暴動癱瘓日本對門的控制。"
    ]
  },
  "relationships": {
    "迪亞波·索爾·凱薩": {
      "nature": "交易對象、不穩定且昂貴的代理人",
      "description": "最初試圖通過與迪亞波的合作來控制門，但因中國開出的條件（全面移民及軍事進駐）過於苛刻，導致迪亞波心生恐懼並最終拒絕成為其完全的傀儡。"
    },
    "劉": {
      "nature": "得力部下、情報執法者",
      "description": "他是董德愁在特區秘密行動的尖兵。董對其寄予厚望，但在劉行動失敗並死亡後，董迅速切斷聯繫以規避政治責任。"
    },
    "高垣周作": {
      "nature": "政治對手、博弈對象",
      "description": "作為日本首相，高垣是阻礙中國進入特區的最大障礙。董德愁在外交與秘密戰線上與其展開了激烈的“超限戰”。"
    },
    "黎紫萱": {
      "nature": "未完全受控的資產、殘餘勢力",
      "description": "據點被毀後倖存的軍事骨幹。儘管董與中南海對其在特區的“獨立行動”持觀察態度，但也準備隨時將其作為刺向日本利益的暗樁。"
    }
  }
}

