  "relationships": {
    "德莉拉": {
      "nature": "同僚、搭档、保护者",
      "description": "两人常在同一班次工作。由于朵拉性格温顺不喜冲突，遇到挑衅或难缠的客人（如姚最初闹事时）通常由好战的德莉拉出面摆平。"
    },
    "伊丹耀司": {
      "nature": "经常照顾生意的豪爽顾客、传闻中的英雄",
