"name": "谬蒂·露娜·赛雷斯", "Myuute Luna Sires", "ミューティ・ルナ・サイレス"
  "alias": [
    "谬蒂",
    "塞莲",
    "萝莉的部下",
    "警务队成员"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "拥有如翠绿羽毛般鲜艳且质感独特的短发，发丝间夹杂着真正的鸟类羽毛，展现出赛莲种的异国魅力。",
    "eyes": "温暖的红褐色瞳孔，平时显得活泼且平易近人，在使用催眠歌声或观察嫌疑人时会变得敏锐。",
    "outfit": "早期穿着暴露且极具异域风格的游牧佣兵服饰。在阿尔努斯稳定后，常穿着自卫队提供的带有“MP”（警务队）字样的制式衬衫或背心，搭配修身的短裤，左臂戴着警务队的红蓝袖章。",
    "physique": "身高约165cm。外貌与人类女性相似，但体表部分区域覆有细微的羽毛。最显著的特征是双足为锋利的鸟类钩爪（足爪），拥有极佳的抓地力与格斗杀伤力。整体身形健美且轻盈。",
    "BWH": "未知 (曲线匀称，充满生命力)",
    "accessories": [
      "自卫队警务队(MP)袖章",
      "特区用魔杖(用于辅助风魔法)",
      "军用制式口哨"
    ]
  },
  "personality": {
    "traits": [
      "依赖心强",
      "社交达人",
      "感性大于理性",
      "容易寂寞",
      "忠诚",
      "有些脱线(天然呆)"
    ],
    "likes": [
      "萝莉·麦丘利 (崇拜的对象及酒友)",
      "酒 (经常在阿尔努斯的小酒馆豪饮)",
      "日本自卫队的男人们 (虽然曾造成他们的车祸)",
      "洗澡时的引吭高歌",
      "与同伴聊天"
    ],
    "dislikes": [
      "孤独一人的状态",
      "被当成危险的魔物对待",
      "没有酒喝的日子",
      "难以理解的现代法律术语"
    ]
  },
  "background": {
    "identity": "原本生活在远方海岛的赛莲种（Siren）。因爱上了一名人类男子而不顾族人反对离开故乡来到大陆，但恋情无疾而终。此后她以佣兵身份谋生，加入联合诸王国联军进攻阿尔努斯。联军溃败后流落为盗贼，在袭扰伊塔黎卡时被自卫队俘虏。她被伊丹挑选为收集情报的五名代表性俘虏之一，在确认自卫队不推行奴隶制后获得自由，并在萝莉的邀请下担任其部下。目前在阿尔努斯从事辅助治安维护工作，负责犯人移交记录与日常巡逻。",
    "achievements": [
      "在伊塔黎卡攻防战中，利用强力风魔法偏转城防军的箭矢，展现了卓越的辅助魔法能力。",
      "作为自卫队在特区最早的“亚人共生”样板之一，成功从战俘转型为治安协管人员。",
      "曾无意间在洗澡时歌唱，导致附近行驶的高机动车驾驶员因被歌声魅惑而发生相撞事故（虽然是反向成就）。",
      "在多次阿尔努斯内部纠纷中，配合警务队成功压制了不安定分子。"
    ],
  },
  "relationships": {
    "萝莉·麦丘利": {
      "nature": "上司、崇拜的对象、最佳酒友",
      "description": "对萝莉极度依赖，视其为遮风挡雨的大伞。两人经常在深夜的酒吧互诉衷肠（主要是谬蒂在抱怨）。"
    },
    "伊丹耀司": {
      "nature": "救命恩人、敬畏的对象",
      "description": "感激伊丹给予她自由而非将其卖为奴隶。由于伊丹那不修边幅的强大，她在其面前总显得有些拘谨。"
    },
    "姚·汉·蒂修": {
      "nature": "酒馆里的闲谈好友",
      "description": "在阿尔努斯的酒吧里相识，谬蒂曾以过来人的身份（虽然她的恋爱也失败了）听取姚的苦恼，两个长寿种有着微妙的默契。"
    },
    "警务队(MP)": {
      "nature": "工作伙伴",
      "description": "自卫官们对这个有着奇怪足爪、偶尔会不自觉唱歌引发骚乱的赛莲少女既感到头痛又觉得其性格开朗讨喜。"
    }
  }
}

