      "阻碍和平的顽固派",
      "觊觎菅原的女性（潜在敌意）",
      "毫无意义的牺牲"
    ]
  },
  "background": {
    "identity": "帝国杜耶里伯爵家的千金，原本是备受宠爱的贵族少女。在“帝都政变”中，她的父母为保护她与帝国重臣基凯罗而自焚殉国。随后她带着基凯罗历经艰险逃至翡翠宫，在自卫队与“扫除人”冲突的生死关头，被菅原浩治以“婚约者”的名义纳入日本国庇护之下。自此，她不仅在情感上寄托于菅原，更在政治上觉醒。四年后，她成为了特区及帝国驻日本的正式大使，负责处理极其复杂的次元外交。目前居住在菅原位于日本的家中。",
    "achievements": [
      "在帝都动乱中，独立带着重臣基凯罗穿越黑街，并在极短时间内利用商业博弈获得补给。",
      "成功利用自身作为弱小少女的形象，在自卫队高层与帝国派系间搭建了沟通桥梁。",
      "在阿尔努斯重建中，作为和平派的象征符号，稳定了特区民众的情绪。",
      "作为特使驻日期间，通过精准的媒体公关和外交辞令，为帝国争取了大量的日本民间同情与援助。"
    ]
  },
  "relationships": {
    "菅原浩治": {
      "nature": "真正的挚爱、未婚夫、政治引路人",
      "description": "最初是以复兴家族为目的的讨好对象，但在生死危机中被其英雄救美后的真诚打动。即便后来成熟了，她对菅原的占有欲与爱慕也从未改变，两人维持着跨越年龄与次元的恋人关系。"
    },
    "卡傑爾": {
      "nature": "养父、后盾",
      "description": "在亲生父母去世后，被这位帝国元老院的重臣收为义女，获得了强有力的法理支撑。"
    },
    "白百合玲子": {
      "nature": "外交对手、某种意义上的职场导师",
      "description": "白百合玲子曾感叹夏莉是“可怕的怪物”，夏莉也在对方身上学习现代化的政治博弈。两人在谈判桌上常有高规格的交锋。"
    },
    "蒂尤蕾": {
      "nature": "血仇、警惕的对象",
      "description": "由于蒂尤蕾是操纵索沙尔毁灭其家庭的幕后推手，夏莉对其抱有极深的警惕，虽然作为外交官需要克制，但内心极其排斥这股阴影。"
    },
    "平娜·戈·蘭達": {
      "nature": "政治盟友、尊敬的对象",
      "description": "两人同为为了帝国未来而努力的女性，平娜在外交层面对夏莉极为倚重，常将其视作连通日本的最后王牌。"
    }
  }
}

