  "background": {
    "identity": "“帝国”皇帝摩尔特的长子，原本的顺位继承人。他是一个典型的巨婴式统治者，试图通过恢复古代帝国的武力霸权来证明自己。他通过欺骗灭绝了猎头兔族，并将女王蒂尤蕾纳为泄欲工具。在“门”之战中，他坚持主战，并在父亲病重时发动政变，建立恐怖统治。由于缺乏基本常识且拒绝接受现代化差距，他成为了蒂尤蕾复仇计划中的傀儡，最终导致帝国陷入内战。在决战失败后，他在绝望中被蒂尤蕾刺杀，并与其同归于尽。他的统治被特区史学家评价为帝国史上最黑暗、最愚蠢的篇章。",
  },
  "relationships": {
    "摩尔特·索尔·阿乌格斯泰斯": {
      "nature": "父亲、竞争对手、怨恨对象",
      "description": "认为父亲软弱，甚至不惜通过下毒来篡位。"
    },
    "蒂尤蕾": {
      "nature": "泄欲工具、唯一信赖的智囊、最终的杀身仇人",
      "description": "虽然虐待她，却在心理上对其产生了严重的依赖，完全没有意识到对方一直在操纵他走向灭亡。"
    },
    "伊丹耀司": {
      "nature": "不共戴天的死敌、噩梦来源",
      "description": "在皇宫遭遇战中因伊丹的威胁而留下了严重的恐声心理创伤。"
    },
    "栗林志乃": {
      "nature": "施暴者与恐惧对象",
      "description": "在帝都被栗林当众痛击并打掉牙齿，这一肉体上的挫败严重打击了他的自尊心。"
    },
    "平娜·戈·兰达": {
      "nature": "同父异母的妹妹、政敌、被其轻视的对象",
      "description": "由于平娜的非嫡系出身而一直低看她，甚至在政变后试图羞辱她，却最终败在平娜的正统政府手中。"
    },
    "古田均": {
      "nature": "被其认可的“厨神”",
      "description": "在暴虐的一面下，对能满足其口腹之欲的古田展现了难得的大度。"
    }
  }
}

