      "被轻视其贵族身份",
      "任何形式的战败与羞辱"
    ]
  },
  "background": {
    "identity": "“帝国”的主战派将军，曾是平娜创立的蔷薇骑士团早期成员。出身于较低等级的男爵家庭，这导致他拥有极强的上位欲望。在银座事件中随军入侵，被日本政府俘虏，经历了他认为毕生最大的奇辱。获释回国后，他背弃了骑士团的理想，投靠索沙尔皇子，利用其对日本制度的浅薄了解，策划了一系列针对平娜正统政府和自卫队的恐怖焦土战术，包括指使哥布林袭击村落、伪装自卫队杀戮平民等。最终在伊塔黎卡决战中试图死战不退以挽回面子，却再次败北被俘。",
    ],
  },
  },
  "relationships": {
    "索沙尔·埃·凯萨": {
      "nature": "效忠的对象、价值观共鸣者",
      "description": "他视索沙尔为唯一能让他飞黄腾达的主君，两者同样具备反理智的狂热。"
    },
    "平娜·戈·蘭達": {
      "nature": "仇恨对象、曾经的团长",
      "description": "极度厌恶平娜，认为女性不应领导自己，并在战场上不择手段地试图摧毁平娜的声望。"
    },
    "蒂尤蕾": {
      "nature": "共事者、某种程度上的崇拜对象",
      "description": "作为索沙尔的将军，他认同蒂尤蕾提供的残酷策略，虽有轻视亚人的倾向，但在权力面前选择了服从。"
    },
    "格雷·戈·奧爾多": {
      "nature": "曾经的指导教官",
      "description": "虽然接受过格雷的教导，但由于阶级差异和价值观的彻底背离，对其完全没有敬意。"
    }
  }
}

