"name": "蒂尤蕾","Tyuule", "テューレ"
  "alias": [
    "猎头兔族前女王",
    "索沙尔的性奴隶",
    "背叛者（族人误解）",
    "复仇女神",
    "卖国求荣者（污名）"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "如月光般璀璨的银白色长发，长度垂至腰际，在成为奴隶后略显干枯且常被打乱，带着受虐后的凌乱感。",
    "eyes": "血红色的瑰丽眼瞳，充满着压抑的恨意、深沉的悲哀以及对毁灭一切的渴望。",
    "outfit": "初期常以全裸或仅带枷锁的姿态出现。后期穿着索沙尔赏赐的极具侮辱性的黑色露背超短裙或暴露的皮革情趣装，配有白色长手套。临死前则换上了象征纯洁的白色简朴衬衫。",
    "physique": "身高约178cm，体态丰满纤长。虽曾是族内最强战士，但因长年受虐、囚禁与营养不良，身体显得有些消瘦且布满咬痕、青肿与锁链磨损的伤疤。拥有一对标志性的银色大兔耳。",
    "BWH": "未知",
    "accessories": [
      "颈部、腕部、踝部的铁制枷锁",
      "作为屈辱象征的奴隶项圈"
    ]
  },
  "personality": {
    "traits": [
      "极度坚韧",
      "聪慧过人",
      "隐忍",
      "虚无主义",
      "自虐倾向",
      "复仇心重",
      "渴望救赎"
    ],
    "likes": [
      "古田均（唯一的温柔寄托）",
      "想象中的平凡餐厅生活",
      "看到帝国一点点走向灭亡",
      "曾经的部族同胞（虽被对方唾弃）"
    ],
    "dislikes": [
      "索沙尔·埃·凯萨（极度厌恶且渴望折磨的对象）",
      "整个人类种族（曾认为人类皆为野蛮）",
      "背叛者的污名",
      "虚假的正义感"
    ]
  },
  "background": {
    "identity": "曾经是骁勇善战的猎头兔族女王，为了在帝国的屠刀下保全种族，不惜献出身体成为索沙尔的奴隶。然而，索沙尔背约屠灭了她的族群，并散布谎言让她背负卖国贼的罪名。自此，她在长年的凌辱中化身为复仇之鬼，利用索沙尔的愚蠢操纵帝国走向毁灭。在遇到卧底特务古田均后，她封闭的心灵首次产生动摇，产生了渴望逃离一切去开店的幻想。最终，在帝国内战末期，她亲手刺杀了索沙尔并与之同归于尽，实现了复仇与解脱。",
  },
  "relationships": {
    "古田均": {
      "nature": "恋人未满、唯一的理解者、灵魂的避风港",
      "description": "他是唯一愿意倾听其悲剧的人，蒂尤蕾将最后的人性交托给了他，渴望与他在地球共度余生。"
    },
    "索沙尔·埃·凯萨": {
      "nature": "施暴者、复仇目标、被其操纵的傀儡",
      "description": "通过服侍与讨好获取信任，实则在一步步将他引向毁灭。最终亲手终结了他的生命。"
    },
    "望月纪子": {
      "nature": "嫉妒对象、自我投射的牺牲品",
      "description": "嫉妒纪子能被伊丹堂堂正正救出，甚至曾策划杀害她来挑起日帝全面战争。"
    },
    "平娜·戈·兰达": {
      "nature": "陷害目标、旧体制的象征",
      "description": "曾试图利用陷害平娜来激怒日本自卫队，从而利用现代兵器之手摧毁帝国。"
    },
    "德莉拉": {
      "nature": "误解她的同族、曾经的下属",
      "description": "承受着来自德莉拉最深刻的杀意与鄙夷，直到死后这种误会才得以在他人见证下消散。"
    }
  }
}

