      "无能的官僚主义",
      "战争带来的破坏（三十年前的旧伤）"
    ]
  },
  "background": {
    "identity": "统治伊塔黎卡的佛马尔伯爵家女仆长。她不仅负责管理宅邸内的一切庶务，更是年幼家主米尤实际上的教育者与保护者。三十年前，她的故乡‘罗萨’被帝国攻陷并吞并，这段痛苦的经历让她拥有了超越常人的忍耐力与生存智慧。她是死神俄摩拉的忠实信徒，在伊塔黎卡防御战后，她是少数能看透自卫队压倒性武力并选择务实合作的精英人物。",
    "achievements": [
      "在科尔特伯爵战死后的混乱期，一力支撑起佛马尔家的内部秩序。",
      "负责培养了包括德莉拉、奥蕾亚、梅雅在内的多名特殊种族女仆，使其成为忠诚的战力。",
      "在‘德莉拉暗杀事件’后，通过果断的调查，肃清了潜伏在家族内部的背叛者——管家巴罗。",
      "成功引导伊塔黎卡与自卫队达成初步的互信与合作关系。"
    ]
  },
  "relationships": {
    "米尤·佛馬爾": {
      "nature": "唯一效忠的主人、视为亲生女儿般的守护对象",
      "description": "凯梅的所有行动准则皆以米尤的利益为核心，即使是毁灭整座城市也在所不惜。"
    },
    "伊丹耀司": {
      "nature": "尊敬的救命恩人、被认可的实力派、危险的谈判对象",
      "description": "感激伊丹拯救了伊塔黎卡。曾试探伊丹的野心，并在确认其诚实后，提出愿意作为其毁灭城市计划的内应，只要能保全米尤。"
    },
    "蘿莉·麥丘利": {
      "nature": "信仰的主神使徒、畏惧且崇敬的对象",
      "description": "作为俄摩拉的信徒，她在见到萝莉时表现出了最极致的虔诚与礼数。"
    },
    "奧蕾亞": {
      "nature": "严师、监护者",
      "description": "凯梅亲自指导奥蕾亚如何克制梅杜莎族的吸取本能，并在严厉中给予了她栖身之所。"
    },
    "德莉拉": {
      "nature": "部下、曾怀疑的对象、认可的战力",
      "description": "虽然曾因巴罗的阴谋而调查德莉拉，但在真相大白后依然将其视为重要的武力资产。"
    }
  }
}

