entries.content:
"name": "杜兰","Duran", "デュラン"
  "alias": [
    "杜兰国王",
    "易北之狮",
    "易北国王",
    "二等身残志坚之王"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "原本是一头深灰色的短发，但在经历阿尔努斯会战的惨烈打击与极度压力后，因玛丽·安托瓦内特综合征而变得全白，透着一种久经风霜的威严感。",
    "eyes": "深邃而锐利的灰色眼瞳，带着看透生死与战场残酷的冷彻，即便身受重伤也未曾失去王者的精气神。",
    "outfit": "战场上穿着厚重的鲜红色重型铠甲，披风在身后猎猎作响，展现出勇猛的易北之狮风采。重伤后在医院通常穿着自卫队的病服，安装义肢后则会在外衣下隐藏钢铁的假肢。",
    "physique": "年近七十，身材魁梧且强悍。虽因战争失去了左臂与左腿，但在安装了日本先进的机械义肢后，依然保持着巅峰人类水平的爆发力与体能，肌肉线条依然坚实。",
    "BWH": "未知",
    "accessories": [
      "战斗用改良义肢 (内置微型弩炮)",
      "易北王室佩剑",
      "标志性的王冠/头饰"
    ]
  },
  "personality": {
    "traits": [
      "沉稳果敢",
      "实用主义",
      "强烈的责任感",
      "憎恨帝国",
      "知恩图报",
      "勇猛",
      "老谋深算"
    ],
    "likes": [
      "易北王国的民众与安宁",
      "日本的高端医疗与义肢技术",
      "正直且有实力的战士 (如伊丹耀司)",
      "为了复国而进行的战略筹划",
      "在直升机上进行的空降作业"
    ],
    "dislikes": [
      "帝国的皇帝摩尔特 (视其为卑劣的背叛者)",
      "自己贪图王位、背叛国家的长子",
      "盲目的自大与毫无意义的送死",
      "被索沙尔派蹂躏的大陆秩序"
    ]
  },
  "background": {
    "identity": "易北王国之王，曾作为帝国从属国的联合军总司令参加阿尔努斯之战。在见证了现代武力的毁灭性后，是少数保持理智且决定与自卫队合作的统治者。他通过出让国内矿产资源（除货币金银外）与税收优惠，成功换取了日本的支持以夺回政权，并成为平娜正统政府在西北方最坚实的军事盟友。",
    "achievements": [
      "在阿尔努斯会战全军覆没的绝境下，单枪匹马向自卫队射出反击之箭并奇迹般生还。",
      "向苦恼中的伊丹耀司提供解决杜嘉精神问题的建议，以此为契机与日本正式建交。",
      "在帝国内乱中支持讲和派，参与了伊塔黎卡保卫战及收复帝都的总击行动。",
      "在直升机被空袭的坠机事故中，以重伤之躯亲手格杀数名索沙尔派精锐并处决了政敌波达文伯爵。"
    ]
  },
  "relationships": {
    "伊丹耀司": {
      "nature": "救命恩人、敬重的战士、忘年交",
      "description": "最初在医院以平民身份接触，被伊丹为了异界少女不惜挑战炎龙的气魄折服，视其为真正可以信任的武人，并授予其易北王国的爵位。"
    },
    "平娜·戈·兰达": {
      "nature": "复杂的政治盟友、曾经的敌视对象",
      "description": "起初因帝国的消耗策略而极度憎恨平娜，但在看到她为了讲和与重建做出的努力后，选择与其达成政治和解，共同对抗索沙尔。"
    },
    "柳田明": {
      "nature": "外交谈判对手、互利的合作者",
      "description": "与柳田进行了充满火药味的复国谈判，虽然在资源开采权上被迫做出巨大让步，但两人在‘现实利益高于一切’的观点上高度一致。"
    },
    "杜嘉·露娜·马尔席": {
      "nature": "曾经的战友家属、引导者",
      "description": "在阿尔努斯医院见证了杜嘉的精神崩溃，并指点伊丹带她去杀掉炎龙以实现‘心灵救赎’。"
    },
    "易北长子": {
      "nature": "背叛者、政敌",
      "description": "杜兰最厌恶的对象，曾趁其重伤失踪时篡夺王位并依附于索沙尔，最终被杜兰率领自卫队彻底清算。"
    }
  }
}

