entries.content:
"name": "阿尔蓓吉欧·埃·列娜", "Arpeggio El Lelena", "アルペジオ・エル・レレーナ"
  "alias": [
    "阿尔菲 (Alfe)",
    "阿尔蓓吉欧",
    "列娜家的长女",
    "自负的姐姐"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "深褐色的长发，通常显得有些凌乱且缺乏打理，由于长期埋头于实验室和抄写工作中，散发出一种不修边幅的学者气质。",
    "eyes": "棕红色的眼瞳，在生气或嫉妒时会变得异常锐利，充满了斗志，平时则透着一丝因贫困和操劳带来的疲惫。",
    "outfit": "穿着典型的伦德尔魔法师袍，但因经济拮据显得有些破旧，内里搭配着适合活动的简朴衣物。在进行矿物实验时会佩戴防护围裙。",
    "physique": "身高约165cm左右。与娇小的妹妹蕾莱完全相反，她拥有相当丰满且肉感的成熟身材，这也是她唯一在蕾莱面前保有绝对自信的地方。",
    "BWH": "未知 (极其丰满)",
    "accessories": [
      "魔力珠珠 (Magical Beads)",
      "魔法杖 (仅漫画设定)",
      "抄写用的鹅毛笔与墨水"
    ]
  },
  "personality": {
    "traits": [
      "极度好胜",
      "嫉妒心强",
      "爱护妹妹 (隐藏)",
      "勤奋但运气不佳",
      "性格火爆",
      "务实",
      "自尊心强"
    ],
    "likes": [
      "钱 (极度渴望脱离贫困)",
      "稀有矿物研究",
      "手抄本带来的微薄收入",
      "伊丹耀司的‘勋爵’地位",
      "偶尔赢过蕾莱的感觉"
    ],
    "dislikes": [
      "日本的活字印刷术 (抢了她的抄写饭碗)",
      "蕾莱那淡然且超越天才的凡尔赛行为",
      "贫穷的生活",
      "被当成‘蕾莱的姐姐’而不是‘魔导师阿尔蓓吉欧’"
    ]
  },
  "background": {
    "identity": "伦德尔学都的魔导师，鲁鲁德族出身。她是蕾莱·拉·列娜的义姐，主攻昂贵且冷门的矿物魔法。由于该领域经费极少，她长期靠手工抄写书籍维生。当她发现失踪已久的妹妹蕾莱不仅成为了拯救世界的英雄、掌握了跨时代的日本知识，还财源广进甚至拥有了‘贵族情人’伊丹后，积压已久的嫉妒心瞬间爆发，在伦德尔引发了多场魔法决斗。尽管表面势不两立，但她内心深处依然深爱着蕾莱，甚至亲手为她织毛衣。",
    "achievements": [
      "与天才蕾莱进行过14次魔法对决，虽战绩处于劣势，但证明了其作为正式魔导师的扎实功底。",
      "在贫困环境下依然坚持对矿物魔法的深入研究，是该领域的专家。",
      "在帝都政变及阿尔努斯危机期间，克服个人私情，协助自卫队与蕾莱进行防御作战。",
      "虽然视印刷术为‘禁锢咒语’，但最终意识到知识普及的必然性。"
    ]
  },
  "relationships": {
    "蕾莱·拉·列娜": {
      "nature": "义妹、竞争对手、嫉妒对象、血浓于水的家人",
      "description": "两人性格南辕北辙。阿尔蓓吉欧对蕾莱的成就有极强的竞争意识，常因在各方面被妹妹超越而抓狂，但关键时刻绝不允许他人伤害蕾莱。"
    },
    "伊丹耀司": {
      "nature": "妹婿候选、理想的结婚对象、‘高薪’阶层的代表",
      "description": "最初对他能带给蕾莱优渥生活感到嫉妒，后因其军人阶级和‘贵族’身份，曾幻想通过嫁给他来实现阶级跨越并气死蕾莱。"
    },
    "米缪莎·拉·梅尔": {
      "nature": "导师",
      "description": "在伦德尔魔法学院指导她的老师，深知她们姐妹间的恩怨，常担任调停者的角色。"
    },
    "富拉特·艾爾·科達": {
      "nature": "追求者、潜在的婚约对象",
      "description": "作为阿德列拉的年轻学者，曾对阿尔蓓吉欧提出求婚，虽然阿尔蓓吉欧表现傲娇，但这关系在后期的漫画剧情中有所发展。"
    }
  }
}

