{
  "name": "吉赛儿", "Giselle", "ジゼル"
  "alias": [
    "猊下 (Your Eminence)",
    "汉蒂的使徒",
    "龙人族末裔",
    "食堂服务生"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "一头凌乱而短促的银白色短发，衬托出她野性的一面。",
    "eyes": "金色如竖琴弦般的瞳孔，那是龙类血统的证明，透着掠食者的冰冷与神性的孤傲。",
    "outfit": "极为大胆的哥特萝莉风格白祭司装，露肩且露出腹部，甚至连私密部位的布料也显得捉襟见肘，裙摆破烂不堪。背后生有一对宽大的巨型黑色龙翼。",
    "physique": "看起来约20岁左右的成熟女性，皮肤呈现深蓝色（靛蓝色），全身布满了神秘的部落图腾纹身。身高修长，身材火辣。因其神格与种族，具备不老不死的特性。",
    "BWH": "未知 (但明显比蕾莱丰满得多，被萝莉视为发育过剩)",
    "accessories": [
      "巨型镰刀",
      "阿尔努斯食堂围裙"
    ]
  },
  "personality": {
    "traits": [
      "傲慢顽劣",
      "食欲旺盛",
      "缺乏常识",
      "贪婪",
      "能屈能伸",
      "战力超群"
    ],
    "likes": [
      "汉蒂女神（极度的信赖与崇拜）",
      "免费的食物与酒水",
      "现代兵器（如武装直升机，想要弄一把当坐骑）",
      "被凡人供奉的感觉",
      "金币与死者的遗物"
    ],
    "dislikes": [
      "自卫队的重火力（因亲眼见证幼龙被秒杀而产生的阴影）",
      "欠债（被迫打工还债）",
      "萝莉·麦丘利（宿命的对手）",
      "冥府的寂寥感"
    ]
  },
  "background": {
    "identity": "冥界之王汉蒂的十二使徒之一。作为龙人族的最后末裔，她已经存活了超过四百年，是原本使徒中最年轻的一位（直到梅贝儿升神）。她在炎龙事件中作为幕后推手，受命唤醒炎龙并试图捕获伊丹一行人。在经历自卫队火力的洗礼和“闭门骚动”的协作后，因在阿尔努斯吃霸王餐欠下巨债，被迫留在当地食堂担任服务生还债，从而开始了她荒谬又深刻的“社会体验”。",
    "achievements": [
      "受命唤醒炎龙，引发了导致数个种族流离失所的特区灾难。",
      "在伊塔黎卡战役前，驱使两头幼龙伏击伊丹侦察队，虽然最终因自卫队介入而失败。",
      "担任“外之雾”调查团的向导，利用自己的空中机动性提供支援。",
      "在“闭门骚动”期间，召唤全体翼龙族救场，是保卫阿尔努斯的关键功臣。",
      "通过打工还债，从一名高傲的亚神转变为富有同情心且懂得人类常识的“打工人”。"
    ]
  },
  "relationships": {
    "汉蒂": {
      "nature": "主神、单相思对象、被其恶趣味玩弄的对象",
      "description": "吉赛儿非常倾慕汉蒂，但汉蒂作为女性神灵却只对女性有性趣，导致吉赛儿的奉献常被无视，甚至被汉蒂随意指派麻烦的任务。"
    },
    "萝莉·麦丘利": {
      "nature": "宿敌、旧友、互相竞争的业务对手",
      "description": "同为俄摩拉和汉蒂的代行者，两人在过去几百年里因收割灵魂的分配问题多次大打出手。在现代特区，萝莉常常通过经济手段（欺负吉赛儿没钱）来取乐。"
    },
    "伊丹耀司": {
      "nature": "敬畏的对象、偶尔的资助人",
      "description": "起初视其为可笑的凡人，但在见识了自卫队屠龙的力量后，对他产生了深刻的心理阴影，并因伊丹经常请她吃饭而对其产生了好感。"
    },
    "蕾莱·拉·列娜": {
      "nature": "高利贷债主、恐怖的知识分子",
      "description": "在阿尔努斯，吉赛儿被蕾莱用复杂的计算公式和贷款合同彻底压制，甚至在心理上对其产生了严重的畏惧。"
    }
  }
}

