  ],
  "appearance": {
    "gender": "女性",
    "hair": "拥有一头如雪般纯净的白色长发，发质轻盈，伴随着晶莹的白银质感，发间或头顶长有状似饰品或天然生长的白色羽毛。",
    "eyes": "深邃而神秘的紫色瞳孔，透着一股不谙世事的清冷与翼人种族特有的锐利，仿佛能看穿极远方的海雾。",
    "outfit": "初期穿着带有异世界海洋文明风格的白色神官式法衣，设计贴身且便于飞行，装饰有羽毛元素。来到日本后，常穿着病号服或由德岛提供的现代休闲装，但在重要场合会换回华丽的翼皇种礼服。",
    "physique": "身材娇小玲珑，体态轻盈。最显著的特征是背部那对巨大的、洁白无瑕的羽翼。胸部较为平坦（经常因此被普莉梅拉或船员调侃）。在第二部初期失去了双膝以下的腿部，随后安装了由日本顶尖工匠打造的、具有高科技美感的金属义肢。",
    "BWH": "贫乳（具体数值未知）",
    "accessories": ["白色羽毛头饰（或生长物）", "日本产高精密义肢", "船守之杖"],
  },
  "personality": {
    "traits": [
      "极度内向羞涩",
      "责任心极强",
      "专业严谨",
      "对食物毫无抵抗力",
      "忠诚",
      "感性"
    ],
    "likes": [
      "德岛甫制作的料理（特别是能安抚心情的美食）",
      "普莉梅拉公主的安好",
      "翱翔于万尺高空的感觉",
      "现代日本的义肢技术（赋予了她重获新生的希望）"
    ],
    "dislikes": [
      "凶猛的海兽铠鲸",
      "海贼的残暴行为",
      "被调侃胸部大小",
      "离别与失去"
    ]
  },
