      "nature": "救命恩人、倾慕对象、食物的供给者、希望能为其生下孩子的男性",
    },
    "普莉梅拉": {
      "nature": "亲友、保护对象、互相支持的政治与情感盟友",

    },
    "江田岛五郎": {
      "nature": "令人畏惧但可靠的长辈、协助者",

    },
    "修拉·诺·亚奇": {
      "nature": "战友、指挥官、理解她伤痛的伙伴",

    }
  }
}

