{
  "name": "普莉梅拉·露娜·阿维翁",
  "alias": [
    "醉姬",
    "碧海的美丽宝珠蒂纳埃",
    "普莉梅拉",
    "阿维翁王国的亡国公主",
    "阿维翁女王"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "拥有一头如落日霞光般的粉橘色长发，发质柔顺，通常会在发顶编成精致的盘发，其余则如波浪般垂至腰间。",
    "eyes": "一双明亮而清澈的红宝石色大眼睛，在平素表现得极度怕生且容易害羞，但在‘醉姬’状态下则会闪烁起锐利且自信的光芒。",
    "outfit": "通常穿着象征蒂纳埃王室身份的高级白色丝绸长裙，裙摆带有精致的刺绣，佩戴珍珠项链。在日本期间曾尝试过各式现代服饰，甚至在媒体前穿着经过改良的、带有悲剧色彩的华丽丧服。",
    "physique": "娇小玲珑且极度白皙，由于出身高贵且备受保护，皮肤如瓷器般细腻。虽看起来柔弱无力，却有着属于王室的高雅气质。",
    "BWH": "未知",
    "accessories": ["珍珠项链", "王家证明文件"]
  },
  "personality": {
    "traits": [
      "极度怕生",
      "双重人格（醉酒后变得好战且果断）",
      "爱国心极强",
      "为了目的不择手段",
      "极度讲究美食",
      "政治直觉敏锐",
      "社交障碍（清醒时）"
    ],
    "likes": [
      "德岛甫制作的高级料理",
      "高品质的酒类",
      "伙伴们（修拉、奥黛特、阿玛莱特）",
      "日本的便利设施",
      "媒体的关注（作为政治手段）"
    ],
    "dislikes": [
      "海贼",
      "由于自己软弱带来的无力感",
      "卑鄙的背叛者（哈拉姆女王、夏姆洛克）",
      "蔬菜（原本挑食，后在德岛教育下有所改善）",
      "被别国作为傀儡摆布"
    ]
  },
  "background": {
    "identity": "蒂纳埃共和国（旧阿维翁王国）的公主，被称为“蒂纳埃的蓝宝石”。她是旧王朝血脉的最后继承者，因此成为各大势力争夺的政治象征。由于长期生活在刺杀与绑架的阴影下，养成了清醒时极度内向、唯有借酒壮胆才能展现王者之风的“醉姬”体质。为了复兴祖国并驱逐肆虐阿维翁海的海贼，她决定跨越“门”前往日本，利用媒体舆论的力量迫使自卫队介入，并最终在亚特兰提亚的动乱中抓住机会，成功复国并登基为女王。"
  },
  "relationships": {
    "德岛甫": {
      "nature": "救命恩人、专属厨师、信赖的支柱",
      "description": "在漂流时被德岛所救，对其厨艺高度认可。虽在性格上经常争吵，但在政治与情感上都极度依赖德岛，并支持其对海贼的剿灭计划。"
    },
    "修拉·诺·阿奇": {
      "nature": "挚友、护卫、值得托付后方的指挥官",
      "description": "两人自幼相识，感情深厚。在普莉梅拉进行外交与媒体博弈时，修拉始终以武力与忠诚护卫左右。"
    },
    "奥黛特·杰·奈维拉": {
      "nature": "亲密的侍女、共同经历苦难的同伴",
      "description": "奥黛特因保护普莉梅拉而失去双腿，普莉梅拉为此心怀愧疚并极力促成其在日本的治疗。"
    },
    "江田岛五郎": {
      "nature": "合作对象、狡猾的战略博弈伙伴",
      "description": "虽然忌惮江田岛的城府，但普莉梅拉意识到必须与这些现代文明的代表合作才能重兴祖国。"
    },
    "北条宗祇": {
      "nature": "政治导师、相互利用的盟友",
      "description": "从北条身上学到了操纵舆论与大国博弈的手段，并得到了日本政府的非官方支持。"
    }
  }
}

