{
  "name": "哈迪", "Hardy", "ハーディ"
  "alias": [
    "冥界之神",
    "地狱统治者",
    "万物终结者"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "多变。由于其神格，能够根据喜好改变发色，通常以一种神秘且带有威压感的色泽呈现，在使用蕾莱的肉体降临时表现为不断延伸的长发。",
    "eyes": "空洞而深邃，蕴含着冥府的虚无与死亡的静谧。在俯瞰凡间时，其眼神透漏出一种视众生为玩物的戏谑。",
    "outfit": "作为神灵本尊时并无固定形态。常以非物质的幽灵或全息投影姿态显现；在降临仪式中，由于其审美倾向，常选择占据拥有优美线条的女性躯体并加以神性装饰。",
    "physique": "不老不死的上位神灵。由于是纯粹的意识体与规则集合，没有固定的肉体限制。她对肉欲和物质享乐有着直白且贪婪的追求。身高与身材随降临载体而定，但通常会调整为丰满且极具诱惑力的状态。",
    "BWH": "未知 (但会根据个人恶趣味强行调整降临载体的丰满度)",
    "accessories": [
      "圣遗物 (圣发)",
      "贝尔纳戈神殿"
    ]
  },
  "personality": {
    "traits": [
      "极度享乐主义",
      "任性放荡",
      "无视常理",
      "贪婪好奇",
      "视众生为蝼蚁",
      "冷酷"
    ],
    "likes": [
      "美丽且强大的女性（如阿芙罗狄忒、萝莉）",
      "新鲜有趣的事物",
      "日本的现代化技术（视为高端玩具）",
      "美味的酒精与食物",
      "观察凡人的痛苦与挣扎"
    ],
    "dislikes": [
      "无趣的现状",
      "男性神灵（称阿努比斯丑陋、对哈迪斯等无感）",
      "自己的计划被阻碍",
      "冥府的寂寥"
    ]
  },
  "background": {
    "identity": "特别地区冥界之王，司掌死亡与地狱的最高位神灵之一。她是‘门’开启的幕后真凶，其目的仅仅是为了在乏味的神灵生涯中寻找乐子。她对帝国和凡人的苦难毫无怜悯，甚至利用炎龙作为清除不稳定因素的工具。在见识到自卫队的降维打击后，她对异世界产生了浓厚的兴趣，并试图将伊丹和蕾莱作为其通往地球的钥匙。尽管她冷酷残忍，但对蕾莱等优秀女性表现出一种变态的占有欲。",
    "achievements": [
      "强行开启‘门’，引发了特区与现代地球的文明碰撞。",
      "暗中引导炎龙袭击，试图利用其制衡自卫队并削减多余的灵魂。",
      "通过占据蕾莱的肉体，向伊丹小队传授了关于时空扭曲与外之雾的终极机密。",
      "与伊丹签订关于‘前往异世界寻找女神’的荒谬协议。",
      "作为世界秩序的操盘手，在幕后玩弄帝国、诸王国与现代国家的博弈。"
    ]
  },
  "relationships": {
    "吉赛儿": {
      "nature": "使徒、工具、呼之即来挥之即去的家仆",
      "description": "哈迪并不关心吉赛儿的死活，仅将其视为执行肮脏任务的代理人，常在任务失败后对其进行羞辱。"
    },
    "萝莉·麦丘利": {
      "nature": "求爱对象、讨厌的晚辈、想强娶的未婚妻",
      "description": "哈迪对比自己神格低的萝莉表现出病态的求婚欲望，曾多次提出要娶萝莉为妻，被萝莉视为噩梦。"
    },
    "蕾莱·拉·列娜": {
      "nature": "理想的载体、感兴趣的研究对象、被其蹂躏的凡人",
      "description": "哈迪极其钟意蕾莱的知性与肉体，常强行降临其身并修改其生理特征以满足自己的恶趣味。"
    },
    "伊丹耀司": {
      "nature": "有趣的观察对象、被迫的导游、契约者",
      "description": "最初视其为微尘，但在伊丹击杀炎龙后对其刮目相看，强迫他必须带自己去日本物色‘新伴侣’。"
    },
    "阿芙罗狄忒": {
      "nature": "跨次元单相思对象、梦中情人",
      "description": "从蕾莱的希腊神话书中得知后，便疯狂迷恋上这位异世界的爱与美之神，甚至将其视为自己新的神生目标。"
    }
  }
}

