    "outfit": "作为帝国高级贵族时，常穿着做工极度繁复、点缀着蕾丝与刺绣的朱红色或深紫色晚礼服。在逃亡并成为亚特兰提亚实际操纵者后，换上了带有海之国风格、既显神圣又带有压抑感的银白色女王长袍，并佩戴着象征王权的珊瑚头冠。",
    "physique": "身高约165-170cm之间，年龄约19-23岁。身材窈窕且曲线优美，有着由于长期社交活动而养成的端庄仪态。白发后的她散发出一种脆弱而又危险的病态美感。",
    "BWH": "未知",
    "accessories": ["白金耳饰", "兰德尔家纹章戒指", "定制的黑色蕾丝面纱"],
  },
  "personality": {
    "traits": [
      "骄傲孤高",
      "自尊心极强",
      "执着且疯狂",
      "深沉的复仇心",
      "社交名媛",
      "病娇倾向",
      "领袖气质"
    ],
    "likes": [
      "已故恋人迪塔的纯真",
      "兰德尔家的往日荣耀",
      "被掌控的秩序",
      "美丽的宝石与矿物",
      "复仇成功的快感"
    ],
    "dislikes": [
      "皇帝摩尔特·索尔·阿乌格斯泰斯",
      "波赛斯·戈·帕蕾丝蒂 (嫉妒其幸福)",
      "自卫队 (视其为杀死恋人的元凶)",
      "自身的私生子身份",
      "背叛与谎言"
    ]
  },
  "background": {
    "identity": "原帝国顶级贵族兰德尔公爵的养女，帝国皇帝摩尔特的侄女。真实身分是前皇太子卡迪与鲁鲁多族女性葵的私生女。在养父去世、领地被没收、府邸被焚以及恋人迪塔战死等绝望深渊中，得知了自己父母被害的真相。她利用重塑“门”的机会进行大规模破坏，并造成日本与特区的时间偏差。被流放后在阿特兰提亚化身为幕后统治者，试图通过操纵地缘政治向帝国与自卫队复仇。其阴谋造成了特区史上最大规模的国际骚乱，被评价为“在美丽外表下隐藏着足以毁灭世界之毒的女人”。",
  },
  "relationships": {
    "摩尔特·索尔·阿乌格斯泰斯": {
      "nature": "亲叔叔、杀父仇人、毁灭一生的主使",
      "description": "极度痛恨摩尔特，将其视为夺走自己一切的万恶之源。"
    },
    "迪塔·柯·埃文": {
      "nature": "唯一的恋人、纯真爱情的化身、黑化的主因",
      "description": "其死讯是蕾蒂彻底崩溃的最后一根稻草。"
    },
    "波赛斯·戈·帕蕾丝蒂": {
      "nature": "宿命的嫉妒对象、旧敌",
      "description": "嫉妒波赛斯能获得完美的爱情与家庭，并早于自己生育。"
    },
    "石原莞吾": {
      "nature": "交易伙伴、互相利用、复杂的政治共犯",
      "description": "在亚特兰提亚与之勾结，利用石原的智谋实现复仇，同时也被石原操纵。"
    },
    "平娜·戈·兰达": {
      "nature": "堂妹、政治对手、同情者的厌恶",
      "description": "虽然接受过平娜的保护，但对平娜那种理想主义的政治观感到极度不耐和厌恶。"
    },
    "蕾莱·拉·列娜": {
      "nature": "妨碍者、技术上的对手",
      "description": "针对蕾莱重建“门”的工程进行了全方位的阻碍与破坏。"
    }
  }
}

