entries.content:
"name": "沃鲁夫","Wolf", "ヴォルフ"
  "alias": [
    "沃尔夫",
    "阿爾努斯軍事警察 (MP)",
    "自衛隊陪練員",
    "搞笑擔當"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "全身覆盖着浓密的棕灰色皮毛，颈部和头部周围有类似狼鬃的修长毛发，展现出沃拉尔登（Volralden）种族典型的野性美。",
    "eyes": "具有犬科特征的明亮眼眸，虽然外表凶猛，但眼神中常带着温和与平易近人的神采，在面对危险时则会转为锐利。",
    "outfit": "执勤时穿着阿尔努斯军事警察（MP）的制式皮甲与自卫队风格的战术背心（带有血迹/磨损痕迹），下半身则穿着便于活动的迷彩长裤。有时会戴着印有自卫队标志的战术手套。",
    "physique": "身高220cm，体型魁梧。全身布满结实的肌肉，兼具怪力和灵敏。在混浴场景中被自卫队官兵评价为私密部位“天赋异禀”，拥有惊人的分量。",
    "BWH": "未知",
    "accessories": ["巨大的十字弩", "多功能军刀", "鲁特琴"]
  },
  "personality": {
    "traits": [
      "冷酷坚毅 (战斗时)",
      "友善随和 (日常)",
      "缺乏常识 (对于异界文化)",
      "忠诚可靠",
      "幽默感",
      "有些贪婪但善良"
    ],
    "likes": [
      "用牙膏擦亮盔甲",
      "弹奏鲁特琴",
      "人鱼和亚人少女",
      "自卫队的现代配给品",
      "在桑拿房休息",
      "踢足球 (即使会用嘴叼球并狡辩没用手)"
    ],
    "dislikes": [
      "栗林志乃的脾气 (极度畏惧)",
      "被称为野兽",
      "复杂的日本礼仪",
      "破坏阿尔努斯和平的人"
    ]
  },
  "background": {
    "identity": "出身于冰雪大山脉另一侧“沃沙特森林”的沃拉尔登族人（狼人）。原本是一名雇佣兵，后被自卫队雇佣，担任阿尔努斯当地的军事警察（MP）和格斗训练教官（SP）。虽然外表威猛，却是阿尔努斯最受欢迎的亚人之一。曾经历过惨烈的“蛛型魔（Arachnid）”战争并重伤幸存。他常作为故事中的气氛活跃者，活跃于自卫队与当地亚人的文化交流中。",
    "achievements": [
      "在阿尔努斯防卫战中，多次带队清理潜入的帝国工作员。",
      "作为教官，促使自卫队改进了针对亚人士兵的残酷CQB战术。",
      "协助萝莉·麦丘利（在魔像化时期）夺回神体，并参与了废弃修道院的突袭行动。",
      "因极佳的耐力与战斗力，被选拔进入阿尔努斯的多种族混合治安部队。"
    ]
  },
  "relationships": {
    "栗林志乃": {
      "nature": "陪练搭档、恐惧的对象、偶尔帮他揉背的对象",
      "description": "沃鲁夫被栗林的怪力和暴脾气深深折服，在她面前就像一只温顺的大狗。栗林偶尔会因为把他当成“巨型抱枕”或揉背的对象而展现出微妙的友好。"
    },
    "梅雅": {
      "nature": "暧昧对象、浴室伙伴",
      "description": "沃鲁夫与猫耳娘梅雅关系亲密，在桑拿房或日常互动中常被众人戏称为一对。"
    },
    "伊丹耀司": {
      "nature": "雇主、值得尊敬的战友",
      "description": "认可伊丹作为领导者的魅力，认为他那种‘为了同伴违抗命令’的精神很合胃口。"
    },
    "吉赛儿": {
      "nature": "由于怜悯给予资助的对象、竞争对手",
      "description": "虽然认为吉赛儿导致炎龙灾难是自作自受，但在看到她打工还债的窘境时会给予金钱资助。"
    },
    "萝莉·麦丘利": {
      "nature": "崇拜对象、曾经的雇主",
      "description": "沃鲁夫曾在幻觉/梦境或过去中协助过萝莉，并在他的鲁特琴头部刻有萝莉的头像以示尊敬。"
    }
  }
}

